from __future__ import annotations
import os, typing as t, click, inflection, openllm
if t.TYPE_CHECKING: from openllm._typing_compat import DictStrAny

def echo(text: t.Any, fg: str = "green", _with_style: bool = True, **attrs: t.Any) -> None:
  attrs["fg"] = fg if not openllm.utils.get_debug_mode() else None
  if not openllm.utils.get_quiet_mode(): t.cast(t.Callable[..., None], click.echo if not _with_style else click.secho)(text, **attrs)

COLUMNS: int = int(os.environ.get("COLUMNS", str(120)))
CONTEXT_SETTINGS: DictStrAny = {"help_option_names": ["-h", "--help"], "max_content_width": COLUMNS, "token_normalize_func": inflection.underscore}
__all__ = ["echo", "COLUMNS", "CONTEXT_SETTINGS"]

import pytest

from openllm_messaging.shared.model_message import (
    ModelMessage,
    Role,
    TOKENS_PLACEHOLDER_VALUE,
)


@pytest.fixture
def message():
    return ModelMessage(role=Role.SYSTEM, content="Hello, world!")


def test_tokens_is_none_for_manually_created_message(message):
    assert message.tokens is None


def test_tokens_is_placeholder_value_if_none(message):
    assert message.as_dict() == {
        "role": "system",
        "content": "Hello, world!",
        "tokens": TOKENS_PLACEHOLDER_VALUE,
    }


def test_as_dict_returns_correct_dict(message):
    message.tokens = 100
    assert message.as_dict() == {
        "role": "system",
        "content": "Hello, world!",
        "tokens": 100,
    }

import asyncio
from openllm_llama2_20_prompt import UserDef as BaseUserDef
from common import get_prompt_set, start_benchmark_session


class UserDef(BaseUserDef):
    @classmethod
    def make_request(cls):
        import openllm
        import json
        import random

        prompt = random.choice(get_prompt_set(300, 500))

        headers = {"accept": "application/json", "Content-Type": "application/json"}
        config = (
            openllm.AutoConfig.for_model("llama")
            .model_construct_env(max_new_tokens=200, top_p=0.21)
            .model_dump()
        )
        data = {"prompt": prompt, "llm_config": config, "adapter_name": None}
        url = f"{cls.BASE_URL}/v1/generate_stream"
        return url, headers, json.dumps(data)


if __name__ == "__main__":
    asyncio.run(start_benchmark_session(UserDef))

