from __future__ import annotations
import logging
import typing as t
from urllib.parse import urljoin
from urllib.parse import urlparse

import httpx
import orjson

import openllm

from .base import BaseAsyncClient
from .base import BaseClient
from .base import in_async_context

if t.TYPE_CHECKING:
    from openllm._types import DictStrAny
    from openllm._types import LiteralRuntime
else:
    DictStrAny = dict

logger = logging.getLogger(__name__)

class HTTPClientMixin:
    if t.TYPE_CHECKING:
        @property
        def _metadata(self) -> DictStrAny: ...
    @property
    def model_name(self) -> str:
        try: return self._metadata["model_name"]
        except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
    @property
    def model_id(self) -> str:
        try: return self._metadata["model_name"]
        except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
    @property
    def framework(self) -> LiteralRuntime:
        try: return self._metadata["framework"]
        except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
    @property
    def timeout(self) -> int:
        try: return self._metadata["timeout"]
        except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
    @property
    def configuration(self) -> dict[str, t.Any]:
        try: return orjson.loads(self._metadata["configuration"])
        except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
    @property
    def supports_embeddings(self) -> bool:
        try: return self._metadata.get("supports_embeddings", False)
        except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
    @property
    def supports_hf_agent(self) -> bool:
        try: return self._metadata.get("supports_hf_agent", False)
        except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
    def postprocess(self, result: dict[str, t.Any]) -> openllm.GenerationOutput:
        return openllm.GenerationOutput(**result)

class HTTPClient(HTTPClientMixin, BaseClient[DictStrAny]):
    def __init__(self, address: str, timeout: int = 30):
        address = address if "://" in address else "http://" + address
        self._host, self._port = urlparse(address).netloc.split(":")
        super().__init__(address, timeout)
    def health(self) -> t.Any: return self._cached.health()
    def embed(self, prompt: t.Sequence[str] | str) -> openllm.EmbeddingsOutput:
        if not self.supports_embeddings:
            raise ValueError("This model does not support embeddings.")
        if isinstance(prompt, str): prompt = [prompt]
        if in_async_context(): result = httpx.post(urljoin(self._address, f"/{self._api_version}/embeddings"), json=list(prompt), timeout=self.timeout)
        else: result = self.call("embeddings", list(prompt))
        return openllm.EmbeddingsOutput(**result)

class AsyncHTTPClient(HTTPClientMixin, BaseAsyncClient[DictStrAny]):
    def __init__(self, address: str, timeout: int = 30):
        address = address if "://" in address else "http://" + address
        self._host, self._port = urlparse(address).netloc.split(":")
        super().__init__(address, timeout)
    async def health(self) -> t.Any: return await self._cached.async_health()
    async def embed(self, prompt: t.Sequence[str] | str) -> openllm.EmbeddingsOutput:
        if not self.supports_embeddings:
            raise ValueError("This model does not support embeddings.")
        if isinstance(prompt, str): prompt = [prompt]
        res = await self.acall("embeddings", list(prompt))
        return openllm.EmbeddingsOutput(**res)

import re
import typing
from typing import Optional

import tabulate
import typer

from openllm.accelerator_spec import DeploymentTarget, can_run
from openllm.analytic import OpenLLMTyper
from openllm.common import VERBOSE_LEVEL, BentoInfo, load_config, output
from openllm.repo import ensure_repo_updated, parse_repo_url

app = OpenLLMTyper(help='manage models')


@app.command(help='get model')
def get(tag: str, repo: Optional[str] = None, verbose: bool = False):
    if verbose:
        VERBOSE_LEVEL.set(20)
    bento_info = ensure_bento(tag, repo_name=repo)
    if bento_info:
        output(bento_info)


@app.command(name='list', help='list available models')
def list_model(tag: Optional[str] = None, repo: Optional[str] = None, verbose: bool = False):
    if verbose:
        VERBOSE_LEVEL.set(20)

    bentos = list_bento(tag=tag, repo_name=repo)
    bentos.sort(key=lambda x: x.name)

    seen = set()

    def is_seen(value):
        if value in seen:
            return True
        seen.add(value)
        return False

    table = tabulate.tabulate(
        [
            [
                '' if is_seen(bento.name) else bento.name,
                bento.tag,
                bento.repo.name,
                bento.pretty_gpu,
                ','.join(bento.platforms),
            ]
            for bento in bentos
        ],
        headers=['model', 'version', 'repo', 'required GPU RAM', 'platforms'],
    )
    output(table)


def ensure_bento(
    model: str,
    target: Optional[DeploymentTarget] = None,
    repo_name: Optional[str] = None,
) -> BentoInfo:
    bentos = list_bento(model, repo_name=repo_name)
    if len(bentos) == 0:
        output(f'No model found for {model}', style='red')
        raise typer.Exit(1)

    if len(bentos) == 1:
        output(f'Found model {bentos[0]}', style='green')
        if target is not None and can_run(bentos[0], target) <= 0:
            output(f'The machine({target.name}) with {target.accelerators_repr} does not appear to have sufficient '
                   f'resources to run model {bentos[0]}\n',
                   style='yellow')
        return bentos[0]

    # multiple models, pick one according to target
    output(f'Multiple models match {model}, did you mean one of these?', style='red')
    list_model(model, repo=repo_name)
    raise typer.Exit(1)


NUMBER_RE = re.compile(r'\d+')


def _extract_first_number(s: str):
    match = NUMBER_RE.search(s)
    if match:
        return int(match.group())
    else:
        return 100


def list_bento(
    tag: typing.Optional[str] = None,
    repo_name: typing.Optional[str] = None,
    include_alias: bool = False,
) -> typing.List[BentoInfo]:
    ensure_repo_updated()

    if repo_name is None and tag and "/" in tag:
        repo_name, tag = tag.split("/", 1)

    if repo_name is not None:
        config = load_config()
        if repo_name not in config.repos:
            output(f'Repo `{repo_name}` not found, did you mean one of these?')
            for repo_name in config.repos:
                output(f'  {repo_name}')
            raise typer.Exit(1)

    if not tag:
        glob_pattern = 'bentoml/bentos/*/*'
    elif ':' in tag:
        bento_name, version = tag.split(':')
        glob_pattern = f'bentoml/bentos/{bento_name}/{version}'
    else:
        glob_pattern = f'bentoml/bentos/{tag}/*'

    model_list = []
    config = load_config()
    for _repo_name, repo_url in config.repos.items():
        if repo_name is not None and _repo_name != repo_name:
            continue
        repo = parse_repo_url(repo_url, _repo_name)

        paths = sorted(
            repo.path.glob(glob_pattern),
            key=lambda x: (x.parent.name, _extract_first_number(x.name), len(x.name), x.name),
        )
        for path in paths:
            if path.is_dir() and (path / 'bento.yaml').exists():
                model = BentoInfo(repo=repo, path=path)
            elif path.is_file():
                with open(path) as f:
                    origin_name = f.read().strip()
                origin_path = path.parent / origin_name
                model = BentoInfo(alias=path.name, repo=repo, path=origin_path)
            else:
                model = None
            if model:
                model_list.append(model)

    if not include_alias:
        seen = set()
        model_list = [
            x
            for x in model_list
            if not (
                f"{x.bento_yaml['name']}:{x.bento_yaml['version']}" in seen
                or seen.add(f"{x.bento_yaml['name']}:{x.bento_yaml['version']}")
            )
        ]
    return model_list

from __future__ import annotations

import asyncio, time, typing, os
import httpx, openai

from openai.types.chat import ChatCompletionAssistantMessageParam, ChatCompletionUserMessageParam
from openllm.common import (
  BentoInfo,
  EnvVars,
  async_run_command,
  output,
  run_command,
  stream_command_output,
)
from openllm.venv import ensure_venv

if typing.TYPE_CHECKING:
  from openai.types.chat import ChatCompletionMessageParam


def prep_env_vars(bento: BentoInfo) -> None:
  env_vars = bento.envs
  for env_var in env_vars:
    if not env_var.get('value'):
      continue
    key = env_var['name']
    value = env_var['value']
    os.environ[key] = value


def _get_serve_cmd(
  bento: BentoInfo, port: int = 3000, cli_args: typing.Optional[list[str]] = None
) -> tuple[list[str], EnvVars]:
  cmd = ['bentoml', 'serve', bento.bentoml_tag]
  if port != 3000:
    cmd += ['--port', str(port)]

  # Add CLI arguments if provided
  if cli_args:
    for arg in cli_args:
      cmd += ['--arg', arg]

  return cmd, EnvVars({'BENTOML_HOME': f'{bento.repo.path}/bentoml'})


def serve(
  bento: BentoInfo,
  port: int = 3000,
  cli_envs: typing.Optional[list[str]] = None,
  cli_args: typing.Optional[list[str]] = None,
) -> None:
  prep_env_vars(bento)
  cmd, env = _get_serve_cmd(bento, port=port, cli_args=cli_args)

  # Add CLI environment variables if provided
  if cli_envs:
    for env_var in cli_envs:
      if '=' in env_var:
        key, value = env_var.split('=', 1)
        env[key] = value
      else:
        env[env_var] = os.environ.get(env_var, '')

  venv = ensure_venv(bento, runtime_envs=env)
  output(f'Access the Chat UI at http://localhost:{port}/chat (or with you IP)')
  run_command(cmd, env=env, cwd=None, venv=venv)


async def _run_model(
  bento: BentoInfo,
  port: int = 3000,
  timeout: int = 600,
  cli_env: typing.Optional[dict[str, typing.Any]] = None,
  cli_args: typing.Optional[list[str]] = None,
) -> None:
  cmd, env = _get_serve_cmd(bento, port, cli_args=cli_args)

  # Merge cli environment variables if provided
  if cli_env:
    env.update(cli_env)

  venv = ensure_venv(bento, runtime_envs=env)
  async with async_run_command(cmd, env=env, cwd=None, venv=venv, silent=False) as server_proc:
    output(f'Model server started {server_proc.pid}')

    stdout_streamer = None
    stderr_streamer = None
    start_time = time.time()

    output('Model loading...', style='green')
    for _ in range(timeout):
      try:
        resp = httpx.get(f'http://localhost:{port}/readyz', timeout=3)
        if resp.status_code == 200:
          break
      except httpx.RequestError:
        if time.time() - start_time > 30:
          if not stdout_streamer:
            stdout_streamer = asyncio.create_task(
              stream_command_output(server_proc.stdout, style='gray')
            )
          if not stderr_streamer:
            stderr_streamer = asyncio.create_task(
              stream_command_output(server_proc.stderr, style='#BD2D0F')
            )
        await asyncio.sleep(1)
    else:
      output('Model failed to load', style='red')
      server_proc.terminate()
      return

    if stdout_streamer:
      stdout_streamer.cancel()
    if stderr_streamer:
      stderr_streamer.cancel()

    output('Model is ready', style='green')
    messages: list[ChatCompletionMessageParam] = []

    client = openai.AsyncOpenAI(base_url=f'http://localhost:{port}/v1', api_key='local')
    while True:
      try:
        message = input('user: ')
        if message == '':
          output('empty message, please enter something', style='yellow')
          continue
        messages.append(ChatCompletionUserMessageParam(role='user', content=message))
        output('assistant: ', end='', style='lightgreen')
        assistant_message = ''
        stream = await client.chat.completions.create(
          model=(await client.models.list()).data[0].id, messages=messages, stream=True
        )
        async for chunk in stream:
          text = chunk.choices[0].delta.content or ''
          assistant_message += text
          output(text, end='', style='lightgreen')
        messages.append(
          ChatCompletionAssistantMessageParam(role='assistant', content=assistant_message)
        )
        output('')
      except KeyboardInterrupt:
        break
    output('\nStopping model server...', style='green')
    output('Stopped model server', style='green')


def run(
  bento: BentoInfo,
  port: int = 3000,
  timeout: int = 600,
  cli_envs: typing.Optional[list[str]] = None,
  cli_args: typing.Optional[list[str]] = None,
) -> None:
  prep_env_vars(bento)

  # Add CLI environment variables to the process
  env = {}
  if cli_envs:
    for env_var in cli_envs:
      if '=' in env_var:
        key, value = env_var.split('=', 1)
        env[key] = value
      else:
        env[env_var] = os.environ.get(env_var, '')

  asyncio.run(_run_model(bento, port=port, timeout=timeout, cli_env=env, cli_args=cli_args))

from __future__ import annotations
import logging, typing as t
from urllib.parse import urljoin, urlparse
import httpx, orjson, openllm
from .base import BaseAsyncClient, BaseClient, in_async_context
from openllm._typing_compat import DictStrAny, LiteralRuntime

logger = logging.getLogger(__name__)
def process_address(self: AsyncHTTPClient | HTTPClient, address: str) -> None:
  address = address if "://" in address else "http://" + address
  parsed = urlparse(address)
  self._host, *_port = parsed.netloc.split(":")
  if len(_port) == 0: self._port = "80" if parsed.scheme == "http" else "443"
  else: self._port = next(iter(_port))

class HTTPClient(BaseClient[DictStrAny]):
  def __init__(self, address: str, timeout: int = 30):
    process_address(self, address)
    super().__init__(address, timeout)

  def health(self) -> t.Any: return self._cached.health()
  def embed(self, prompt: t.Sequence[str] | str) -> openllm.EmbeddingsOutput:
    if isinstance(prompt, str): prompt = [prompt]
    result = httpx.post(urljoin(self._address, f"/{self._api_version}/embeddings"), json=list(prompt), timeout=self.timeout).json() if in_async_context() else self.call("embeddings", list(prompt))
    return openllm.EmbeddingsOutput(**result)

  @property
  def model_name(self) -> str:
    try: return self._metadata["model_name"]
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  @property
  def model_id(self) -> str:
    try: return self._metadata["model_name"]
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  @property
  def framework(self) -> LiteralRuntime:
    try: return self._metadata["framework"]
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  @property
  def timeout(self) -> int:
    try: return self._metadata["timeout"]
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  @property
  def configuration(self) -> dict[str, t.Any]:
    try: return orjson.loads(self._metadata["configuration"])
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  @property
  def supports_embeddings(self) -> bool:
    try: return self._metadata.get("supports_embeddings", False)
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  @property
  def supports_hf_agent(self) -> bool:
    try: return self._metadata.get("supports_hf_agent", False)
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  def postprocess(self, result: dict[str, t.Any]) -> openllm.GenerationOutput: return openllm.GenerationOutput(**result)

class AsyncHTTPClient(BaseAsyncClient[DictStrAny]):
  def __init__(self, address: str, timeout: int = 30):
    process_address(self, address)
    super().__init__(address, timeout)

  async def health(self) -> t.Any: return await self._cached.async_health()
  async def embed(self, prompt: t.Sequence[str] | str) -> openllm.EmbeddingsOutput:
    if isinstance(prompt, str): prompt = [prompt]
    res = await self.acall("embeddings", list(prompt))
    return openllm.EmbeddingsOutput(**res)

  @property
  def model_name(self) -> str:
