from __future__ import annotations

import re, typing, json
import tabulate, questionary, typer

from openllm.accelerator_spec import can_run
from openllm.common import DeploymentTarget
from openllm.analytic import OpenLLMTyper
from openllm.common import VERBOSE_LEVEL, BentoInfo, output as output_, load_config
from openllm.repo import ensure_repo_updated, list_repo

app = OpenLLMTyper(help='manage models')


@app.command(help='get model')
def get(tag: str, repo: typing.Optional[str] = None, verbose: bool = False) -> None:
  if verbose:
    VERBOSE_LEVEL.set(20)
  bento_info = ensure_bento(tag, repo_name=repo)
  if bento_info:
    output_(bento_info)


@app.command(name='list', help='list available models')
def list_model(
  tag: typing.Optional[str] = None,
  repo: typing.Optional[str] = None,
  verbose: bool = False,
  output: typing.Optional[str] = typer.Option(None, hidden=True),
) -> None:
  if verbose:
    VERBOSE_LEVEL.set(20)

  if repo is None:
    repo = load_config().default_repo

  bentos = list_bento(tag=tag, repo_name=repo)
  bentos.sort(key=lambda x: x.name)

  seen = set()

  def is_seen(value: str) -> bool:
    if value in seen:
      return True
    seen.add(value)
    return False

  if output == 'readme':
    # Parse parameters from bento.tag (e.g. "model:671b-it" -> "671b", 'model:something-long-78b' -> '78b')
    questionary.print(
      json.dumps({
        f'{bento.name}': dict(
          tag=bento.tag,
          version=bento.tag.split(':')[-1],
          pretty_gpu=bento.pretty_gpu,
          command=f'openllm serve {bento.tag}',
        )
        for bento in bentos
        if not is_seen(bento.name)
      })
    )
    return

  table = tabulate.tabulate(
    [
      [
        '' if is_seen(bento.name) else bento.name,
        bento.tag,
        bento.repo.name,
        bento.pretty_gpu,
        ','.join(bento.platforms),
      ]
      for bento in bentos
    ],
    headers=['model', 'version', 'repo', 'required GPU RAM', 'platforms'],
  )
  output_(table)


def ensure_bento(
  model: str,
  target: typing.Optional[DeploymentTarget] = None,
  repo_name: typing.Optional[str] = None,
) -> BentoInfo:
  if repo_name is None:
    from openllm.common import load_config

    repo_name = load_config().default_repo

  bentos = list_bento(model, repo_name=repo_name)
  if len(bentos) == 0:
    output_(f'No model found for {model}', style='red')
    raise typer.Exit(1)

  if len(bentos) == 1:
    output_(f'Found model {bentos[0]}', style='green')
    if target is not None and can_run(bentos[0], target) <= 0:
      output_(
        f'The machine({target.name}) with {target.accelerators_repr} does not appear to have sufficient '
        f'resources to run model {bentos[0]}\n',
        style='yellow',
      )
    return bentos[0]

  # multiple models, pick one according to target
  output_(f'Multiple models match {model}, did you mean one of these?', style='red')
  list_model(model, repo=repo_name)
  raise typer.Exit(1)


NUMBER_RE = re.compile(r'\d+')


def _extract_first_number(s: str) -> int:
  match = NUMBER_RE.search(s)
  if match:
    return int(match.group())
  else:
    return 100


def list_bento(
  tag: typing.Optional[str] = None,
  repo_name: typing.Optional[str] = None,
  include_alias: bool = False,
) -> typing.List[BentoInfo]:
  ensure_repo_updated()

  if repo_name is None and tag and '/' in tag:
    repo_name, tag = tag.split('/', 1)

  repo_list = list_repo(repo_name)
  if repo_name is not None:
    repo_map = {repo.name: repo for repo in repo_list}
    if repo_name not in repo_map:
      output_(f'Repo `{repo_name}` not found, did you mean one of these?')
      for repo_name in repo_map:
        output_(f'  {repo_name}')
      raise typer.Exit(1)

  if not tag:
    glob_pattern = 'bentoml/bentos/*/*'
  elif ':' in tag:
    bento_name, version = tag.split(':')
    glob_pattern = f'bentoml/bentos/{bento_name}/{version}'
  else:
    glob_pattern = f'bentoml/bentos/{tag}/*'

  model_list: list[BentoInfo] = []
  repo_list = list_repo(repo_name)
  for repo in repo_list:
    paths = sorted(
      repo.path.glob(glob_pattern),
      key=lambda x: (x.parent.name, _extract_first_number(x.name), len(x.name), x.name),
    )
    for path in paths:
      if path.is_dir() and (path / 'bento.yaml').exists():
        model = BentoInfo(repo=repo, path=path)
      elif path.is_file():
        with open(path) as f:
          origin_name = f.read().strip()
        origin_path = path.parent / origin_name
        model = BentoInfo(alias=path.name, repo=repo, path=origin_path)
      else:
        model = None
      if model:
        model_list.append(model)

  if not include_alias:
    seen: set[str] = set()
    # we are calling side-effect in seen here.
    model_list = [
      x
      for x in model_list
      if not (
        f'{x.bento_yaml["name"]}:{x.bento_yaml["version"]}' in seen
        or seen.add(f'{x.bento_yaml["name"]}:{x.bento_yaml["version"]}')  # type: ignore
      )
    ]
  return model_list

from __future__ import annotations
import copy, typing as t, openllm
from bentoml._internal.models.model import ModelInfo, ModelSignature
from openllm.serialisation.constants import FRAMEWORK_TO_AUTOCLASS_MAPPING, HUB_ATTRS

if t.TYPE_CHECKING:
  import torch, transformers, bentoml
  from transformers.models.auto.auto_factory import _BaseAutoModelClass
  from bentoml._internal.models.model import ModelSignaturesType
  from openllm._typing_compat import DictStrAny, M, T
else: transformers, torch = openllm.utils.LazyLoader("transformers", globals(), "transformers"), openllm.utils.LazyLoader("torch", globals(), "torch")

_object_setattr = object.__setattr__

def process_config(model_id: str, trust_remote_code: bool, **attrs: t.Any) -> tuple[transformers.PretrainedConfig, DictStrAny, DictStrAny]:
  """A helper function that correctly parse config and attributes for transformers.PretrainedConfig.

  Args:
    model_id: Model id to pass into ``transformers.AutoConfig``.
    trust_remote_code: Whether to trust_remote_code or not
    attrs: All possible attributes that can be processed by ``transformers.AutoConfig.from_pretrained

  Returns:
    A tuple of ``transformers.PretrainedConfig``, all hub attributes, and remanining attributes that can be used by the Model class.
  """
  config = attrs.pop("config", None)
  # this logic below is synonymous to handling `from_pretrained` attrs.
  hub_attrs = {k: attrs.pop(k) for k in HUB_ATTRS if k in attrs}
  if not isinstance(config, transformers.PretrainedConfig):
    copied_attrs = copy.deepcopy(attrs)
    if copied_attrs.get("torch_dtype", None) == "auto": copied_attrs.pop("torch_dtype")
    config, attrs = transformers.AutoConfig.from_pretrained(model_id, return_unused_kwargs=True, trust_remote_code=trust_remote_code, **hub_attrs, **copied_attrs)
  return config, hub_attrs, attrs

def infer_tokenizers_from_llm(__llm: openllm.LLM[t.Any, T], /) -> T:
  __cls = getattr(transformers, openllm.utils.first_not_none(__llm.config["tokenizer_class"], default="AutoTokenizer"), None)
  if __cls is None: raise ValueError(f"Cannot infer correct tokenizer class for {__llm}. Make sure to unset `tokenizer_class`")
  return __cls

def infer_autoclass_from_llm(llm: openllm.LLM[M, T], config: transformers.PretrainedConfig, /) -> _BaseAutoModelClass:
  if llm.config["trust_remote_code"]:
    autoclass = "AutoModelForSeq2SeqLM" if llm.config["model_type"] == "seq2seq_lm" else "AutoModelForCausalLM"
    if not hasattr(config, "auto_map"): raise ValueError(f"Invalid configuraiton for {llm.model_id}. ``trust_remote_code=True`` requires `transformers.PretrainedConfig` to contain a `auto_map` mapping")
    # in case this model doesn't use the correct auto class for model type, for example like chatglm
    # where it uses AutoModel instead of AutoModelForCausalLM. Then we fallback to AutoModel
    if autoclass not in config.auto_map: autoclass = "AutoModel"
    return getattr(transformers, autoclass)
  else:
    if type(config) in transformers.MODEL_FOR_CAUSAL_LM_MAPPING: idx = 0
    elif type(config) in transformers.MODEL_FOR_SEQ_TO_SEQ_CAUSAL_LM_MAPPING: idx = 1
    else: raise openllm.exceptions.OpenLLMException(f"Model type {type(config)} is not supported yet.")
    return getattr(transformers, FRAMEWORK_TO_AUTOCLASS_MAPPING[llm.__llm_implementation__][idx])

def check_unintialised_params(model: torch.nn.Module) -> None:
  unintialized = [n for n, param in model.named_parameters() if param.data.device == torch.device("meta")]
  if len(unintialized) > 0: raise RuntimeError(f"Found the following unintialized parameters in {model}: {unintialized}")

def update_model(bentomodel: bentoml.Model, metadata: DictStrAny) -> bentoml.Model:
  based: DictStrAny = copy.deepcopy(bentomodel.info.metadata)
  based.update(metadata)
  _object_setattr(
      bentomodel, "_info",
      ModelInfo(  # type: ignore[call-arg] # XXX: remove me once upstream is merged
          tag=bentomodel.info.tag, module=bentomodel.info.module, labels=bentomodel.info.labels, options=bentomodel.info.options.to_dict(), signatures=bentomodel.info.signatures, context=bentomodel.info.context, api_version=bentomodel.info.api_version, creation_time=bentomodel.info.creation_time, metadata=based
      )
  )
  return bentomodel

# NOTE: sync with bentoml/_internal/frameworks/transformers.py#make_default_signatures
def make_model_signatures(llm: openllm.LLM[M, T]) -> ModelSignaturesType:
  infer_fn: tuple[str, ...] = ("__call__",)
  default_config = ModelSignature(batchable=False)
  if llm.__llm_implementation__ in {"pt", "vllm"}:
    infer_fn += ("forward", "generate", "contrastive_search", "greedy_search", "sample", "beam_search", "beam_sample", "group_beam_search", "constrained_beam_search",)
  elif llm.__llm_implementation__ == "tf":
    infer_fn += ("predict", "call", "generate", "compute_transition_scores", "greedy_search", "sample", "beam_search", "contrastive_search",)
  else:
    infer_fn += ("generate",)
  return {k: default_config for k in infer_fn}

import json
import os
import pathlib
import shutil
import subprocess
import typing

import typer

from openllm.accelerator_spec import ACCELERATOR_SPECS
from openllm.analytic import OpenLLMTyper
from openllm.common import (INTERACTIVE, BentoInfo, DeploymentTarget, output,
                            run_command)

app = OpenLLMTyper()


def _get_deploy_cmd(bento: BentoInfo, target: typing.Optional[DeploymentTarget] = None):
    cmd = ['bentoml', 'deploy', bento.bentoml_tag]
    env = {'BENTOML_HOME': f'{bento.repo.path}/bentoml'}

    required_envs = bento.bento_yaml.get('envs', [])
    required_env_names = [env['name'] for env in required_envs if 'name' in env]
    if required_env_names:
        output(
            f'This model requires the following environment variables to run: {required_env_names!r}', style='yellow'
        )

    for env_info in bento.bento_yaml.get('envs', []):
        if 'name' not in env_info:
            continue
        if os.environ.get(env_info['name']):
            default = os.environ[env_info['name']]
        elif 'value' in env_info:
            default = env_info['value']
        else:
            default = ''

        if INTERACTIVE.get():
            import questionary

            value = questionary.text(f"{env_info['name']}:", default=default).ask()
        else:
            if default == '':
                output(f"Environment variable {env_info['name']} is required but not provided", style='red')
                raise typer.Exit(1)
            else:
                value = default

        if value is None:
            raise typer.Exit(1)
        cmd += ['--env', f"{env_info['name']}={value}"]

    if target:
        cmd += ['--instance-type', target.name]

    assert (pathlib.Path.home() / 'bentoml' / '.yatai.yaml').exists()
    shutil.copy(pathlib.Path.home() / 'bentoml' / '.yatai.yaml', bento.repo.path / 'bentoml' / '.yatai.yaml')

    return cmd, env, None


def ensure_cloud_context():
    import questionary

    cmd = ['bentoml', 'cloud', 'current-context']
    try:
        result = subprocess.check_output(cmd, stderr=subprocess.DEVNULL)
        context = json.loads(result)
        output(f"  bentoml already logged in: {context['endpoint']}", style='green', level=20)
    except subprocess.CalledProcessError:
        output('  bentoml not logged in', style='red')
        if not INTERACTIVE.get():
            output('\n  get bentoml logged in by:')
            output('    $ bentoml cloud login', style='orange')
            output('')
            output(
                """  * you may need to visit https://cloud.bentoml.com to get an account. you can also bring your own bentoml cluster (BYOC) to your team from https://bentoml.com/contact""",
                style='yellow',
            )
            raise typer.Exit(1)
        else:
            action = questionary.select(
                'Choose an action:', choices=['I have a BentoCloud account', 'get an account in two minutes']
            ).ask()
            if action is None:
                raise typer.Exit(1)
            elif action == 'get an account in two minutes':
                output('Please visit https://cloud.bentoml.com to get your token', style='yellow')
            endpoint = questionary.text('Enter the endpoint: (similar to https://my-org.cloud.bentoml.com)').ask()
            if endpoint is None:
                raise typer.Exit(1)
            token = questionary.text('Enter your token: (similar to cniluaxxxxxxxx)').ask()
            if token is None:
                raise typer.Exit(1)
            cmd = ['bentoml', 'cloud', 'login', '--api-token', token, '--endpoint', endpoint]
            try:
                result = subprocess.check_output(cmd)
                output('  Logged in successfully', style='green')
            except subprocess.CalledProcessError:
                output('  Failed to login', style='red')
                raise typer.Exit(1)


def get_cloud_machine_spec() -> list[DeploymentTarget]:
    ensure_cloud_context()
    cmd = ['bentoml', 'deployment', 'list-instance-types', '-o', 'json']
    try:
        result = subprocess.check_output(cmd, stderr=subprocess.DEVNULL)
        instance_types = json.loads(result)
        return [
            DeploymentTarget(
                source='cloud',
                name=it['name'],
                price=it['price'],
                platform='linux',
                accelerators=(
                    [ACCELERATOR_SPECS[it['gpu_type']] for _ in range(int(it['gpu']))]
                    if it.get('gpu') and it['gpu_type'] in ACCELERATOR_SPECS
                    else []
                ),
            )
            for it in instance_types
        ]
    except (subprocess.CalledProcessError, json.JSONDecodeError):
        output('Failed to get cloud instance types', style='red')
        return []


def deploy(bento: BentoInfo, target: DeploymentTarget):
    ensure_cloud_context()
    cmd, env, cwd = _get_deploy_cmd(bento, target)
    run_command(cmd, env=env, cwd=cwd)

from __future__ import annotations
import logging, typing as t, bentoml, openllm
from openllm._prompt import process_prompt
from openllm.utils import generate_labels, is_triton_available
from .configuration_mpt import DEFAULT_PROMPT_TEMPLATE, MPTPromptType

if t.TYPE_CHECKING: import transformers, torch
else: transformers, torch = openllm.utils.LazyLoader("transformers", globals(), "transformers"), openllm.utils.LazyLoader("torch", globals(), "torch")

logger = logging.getLogger(__name__)
def get_mpt_config(model_id_or_path: str, max_sequence_length: int, device: torch.device | str | int | None, device_map: str | None = None, trust_remote_code: bool = True) -> transformers.PretrainedConfig:
  config = transformers.AutoConfig.from_pretrained(model_id_or_path, trust_remote_code=trust_remote_code)
  if hasattr(config, "init_device") and device_map is None and isinstance(device, (str, torch.device)): config.init_device = str(device)
  if hasattr(config, "attn_config") and is_triton_available(): config.attn_config["attn_impl"] = "triton"
  else: logger.debug("'triton' is not available, Flash Attention will use the default Torch implementation. For faster inference, make sure to install triton with 'pip install \"git+https://github.com/openai/triton.git#egg=triton&subdirectory=python\"'")
  # setting max_seq_len
  config.max_seq_len = max_sequence_length
  return config
class MPT(openllm.LLM["transformers.PreTrainedModel", "transformers.GPTNeoXTokenizerFast"]):
  __openllm_internal__ = True
  def llm_post_init(self) -> None: self.dtype = torch.bfloat16 if torch.cuda.is_available() else torch.float32
  @property
  def import_kwargs(self) -> tuple[dict[str, t.Any], dict[str, t.Any]]: return {"device_map": "auto" if torch.cuda.is_available() and torch.cuda.device_count() > 1 else None, "torch_dtype": torch.bfloat16 if torch.cuda.is_available() else torch.float32}, {}
  def import_model(self, *args: t.Any, trust_remote_code: bool = True, **attrs: t.Any) -> bentoml.Model:
    _, tokenizer_attrs = self.llm_parameters
    torch_dtype = attrs.pop("torch_dtype", self.dtype)
    device_map = attrs.pop("device_map", None)
    attrs.pop("low_cpu_mem_usage", None)
    config = get_mpt_config(self.model_id, self.config.max_sequence_length, self.device, device_map=device_map, trust_remote_code=trust_remote_code)
    tokenizer = transformers.AutoTokenizer.from_pretrained(self.model_id, **tokenizer_attrs)
    if tokenizer.pad_token_id is None: tokenizer.pad_token = tokenizer.eos_token
    model = transformers.AutoModelForCausalLM.from_pretrained(self.model_id, config=config, torch_dtype=torch_dtype, trust_remote_code=trust_remote_code, device_map=device_map, **attrs)
    try: return bentoml.transformers.save_model(self.tag, model, custom_objects={"tokenizer": tokenizer}, labels=generate_labels(self))
    finally: torch.cuda.empty_cache()
  def load_model(self, *args: t.Any, **attrs: t.Any) -> transformers.PreTrainedModel:
    torch_dtype = attrs.pop("torch_dtype", self.dtype)
    device_map = attrs.pop("device_map", None)
    trust_remote_code = attrs.pop("trust_remote_code", True)
    config = get_mpt_config(self._bentomodel.path, self.config.max_sequence_length, self.device, device_map=device_map, trust_remote_code=trust_remote_code,)
    model = transformers.AutoModelForCausalLM.from_pretrained(self._bentomodel.path, config=config, trust_remote_code=trust_remote_code, torch_dtype=torch_dtype, device_map=device_map, **attrs)
    model.tie_weights()
    return model
  def sanitize_parameters(self, prompt: str, max_new_tokens: int | None = None, temperature: float | None = None, top_p: float | None = None, prompt_type: MPTPromptType | None = None, use_default_prompt_template: bool = True, **attrs: t.Any,) -> tuple[str, dict[str, t.Any], dict[str, t.Any]]:
    _template = None
    if use_default_prompt_template:
      if prompt_type is None:
        if "instruct" in self.model_id: prompt_type = "instruct"
        elif "storywriter" in self.model_id: prompt_type = "storywriter"
        elif "chat" in self.model_id: prompt_type = "chat"
        else: prompt_type = "default"
      _template = DEFAULT_PROMPT_TEMPLATE(prompt_type)
    return process_prompt(prompt, _template, use_default_prompt_template), {"max_new_tokens": max_new_tokens, "temperature": temperature, "top_p": top_p}, {}
  def postprocess_generate(self, prompt: str, generation_result: t.Sequence[str], **attrs: t.Any) -> str: return generation_result[0]
  def generate(self, prompt: str, **attrs: t.Any) -> list[str]:
    llm_config = self.config.model_construct_env(**attrs)
    inputs = self.tokenizer(prompt, return_tensors="pt").to(self.device)
    attrs = {"do_sample": False if llm_config["temperature"] == 0 else True, "eos_token_id": self.tokenizer.eos_token_id, "pad_token_id": self.tokenizer.pad_token_id, "generation_config": llm_config.to_generation_config()}
    with torch.inference_mode():
      if torch.cuda.is_available():
        with torch.autocast("cuda", torch.float16):  # type: ignore[attr-defined]
          generated_tensors = self.model.generate(**inputs, **attrs)
      else: generated_tensors = self.model.generate(**inputs, **attrs)
    return self.tokenizer.batch_decode(generated_tensors, skip_special_tokens=True)

from __future__ import annotations

import functools
import math
import typing
from types import SimpleNamespace

import psutil

from openllm.common import BentoInfo, DeploymentTarget, output


class Accelerator(SimpleNamespace):
    model: str
    memory_size: float

    def __gt__(self, other):
        return self.memory_size > other.memory_size

    def __eq__(self, other):
        return self.memory_size == other.memory_size

    def __repr__(self):
        return f'{self.model}({self.memory_size}GB)'


class Resource(SimpleNamespace):
    cpu: int = 0
    memory: float
    gpu: int = 0
    gpu_type: str = ''

    def __hash__(self):
        return hash((self.cpu, self.memory, self.gpu, self.gpu_type))

    def __bool__(self):
        return any(value is not None for value in self.__dict__.values())


ACCELERATOR_SPEC_DICT: dict[str, dict] = {
    'nvidia-gtx-1650': {'model': 'GTX 1650', 'memory_size': 4.0},
    'nvidia-gtx-1060': {'model': 'GTX 1060', 'memory_size': 6.0},
    'nvidia-gtx-1080-ti': {'model': 'GTX 1080 Ti', 'memory_size': 11.0},
    'nvidia-rtx-3060': {'model': 'RTX 3060', 'memory_size': 12.0},
    'nvidia-rtx-3060-ti': {'model': 'RTX 3060 Ti', 'memory_size': 8.0},
    'nvidia-rtx-3070-ti': {'model': 'RTX 3070 Ti', 'memory_size': 8.0},
    'nvidia-rtx-3080': {'model': 'RTX 3080', 'memory_size': 10.0},
    'nvidia-rtx-3080-ti': {'model': 'RTX 3080 Ti', 'memory_size': 12.0},
    'nvidia-rtx-3090': {'model': 'RTX 3090', 'memory_size': 24.0},
    'nvidia-rtx-4070-ti': {'model': 'RTX 4070 Ti', 'memory_size': 12.0},
    'nvidia-tesla-p4': {'model': 'P4', 'memory_size': 8.0},
    'nvidia-tesla-p100': {'model': 'P100', 'memory_size': 16.0},
    'nvidia-tesla-k80': {'model': 'K80', 'memory_size': 12.0},
    'nvidia-tesla-t4': {'model': 'T4', 'memory_size': 16.0},
    'nvidia-tesla-v100': {'model': 'V100', 'memory_size': 16.0},
    'nvidia-l4': {'model': 'L4', 'memory_size': 24.0},
    'nvidia-tesla-l4': {'model': 'L4', 'memory_size': 24.0},
    'nvidia-tesla-a10g': {'model': 'A10G', 'memory_size': 24.0},
    'nvidia-a100-80g': {'model': 'A100', 'memory_size': 80.0},
    'nvidia-a100-80gb': {'model': 'A100', 'memory_size': 80.0},
    'nvidia-tesla-a100': {'model': 'A100', 'memory_size': 40.0},
}

ACCELERATOR_SPECS: dict[str, Accelerator] = {key: Accelerator(**value) for key, value in ACCELERATOR_SPEC_DICT.items()}


@functools.lru_cache
def get_local_machine_spec():
    if psutil.MACOS:
        return DeploymentTarget(accelerators=[], source='local', platform='macos')

    if psutil.WINDOWS:
        platform = 'windows'
    elif psutil.LINUX:
        platform = 'linux'
    else:
        raise NotImplementedError('Unsupported platform')

    from pynvml import (
        nvmlDeviceGetCount,
        nvmlDeviceGetCudaComputeCapability,
        nvmlDeviceGetHandleByIndex,
        nvmlDeviceGetMemoryInfo,
        nvmlDeviceGetName,
        nvmlInit,
        nvmlShutdown,
    )

    try:
        nvmlInit()
        device_count = nvmlDeviceGetCount()
        accelerators: list[Accelerator] = []
        for i in range(device_count):
            handle = nvmlDeviceGetHandleByIndex(i)
            name = nvmlDeviceGetName(handle)
            memory_info = nvmlDeviceGetMemoryInfo(handle)
            accelerators.append(Accelerator(model=name, memory_size=math.ceil(int(memory_info.total) / 1024**3)))
            compute_capability = nvmlDeviceGetCudaComputeCapability(handle)
            if compute_capability < (7, 5):
                output(
                    f'GPU {name} with compute capability {compute_capability} '
                    'may not be supported, 7.5 or higher is recommended. check '
                    'https://developer.nvidia.com/cuda-gpus for more information',
                    style='yellow',
                )
        nvmlShutdown()
        return DeploymentTarget(accelerators=accelerators, source='local', platform=platform)
    except Exception as e:
        output(
            'Failed to get local GPU info. Ensure nvidia driver is installed to enable local GPU deployment',
            style='yellow',
        )
        output(f'Error: {e}', style='red', level=20)
        return DeploymentTarget(accelerators=[], source='local', platform=platform)


@functools.lru_cache()
def can_run(bento: typing.Union[Resource, BentoInfo], target: typing.Optional[DeploymentTarget] = None) -> float:
    """
    Calculate if the bento can be deployed on the target.
    """
    if target is None:
        target = get_local_machine_spec()

    resource_spec = Resource(**(bento.bento_yaml['services'][0]['config'].get('resources', {})))
    labels = bento.bento_yaml.get('labels', {})
    platforms = labels.get('platforms', 'linux').split(',')

    if target.platform not in platforms:
        return 0.0

    # return 1.0 if no resource is specified
    if not resource_spec:
        return 0.5

    if resource_spec.gpu > 0:
        required_gpu = ACCELERATOR_SPECS[resource_spec.gpu_type]
        filtered_accelerators = [ac for ac in target.accelerators if ac.memory_size >= required_gpu.memory_size]
        if resource_spec.gpu > len(filtered_accelerators):
            return 0.0
        return required_gpu.memory_size * resource_spec.gpu / sum(ac.memory_size for ac in target.accelerators)
    if target.accelerators:
        return 0.01 / sum(ac.memory_size for ac in target.accelerators)
    return 1.0

from __future__ import annotations
import asyncio, logging, typing as t
import orjson, openllm
from openllm._typing_compat import LiteralRuntime
from .base import BaseAsyncClient, BaseClient

if t.TYPE_CHECKING:
  from grpc_health.v1 import health_pb2
  from bentoml.grpc.v1.service_pb2 import Response

logger = logging.getLogger(__name__)

class GrpcClient(BaseClient["Response"], client_type="grpc"):
  def __init__(self, address: str, timeout: int = 30):
    self._host, self._port = address.split(":")
    super().__init__(address, timeout)
  def health(self) -> health_pb2.HealthCheckResponse: return asyncio.run(self._cached.health("bentoml.grpc.v1.BentoService"))
  @property
  def model_name(self) -> str:
    try: return self._metadata.json.struct_value.fields["model_name"].string_value
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  @property
  def framework(self) -> LiteralRuntime:
    try:
      value = t.cast(LiteralRuntime, self._metadata.json.struct_value.fields["framework"].string_value)
      if value not in ("pt", "flax", "tf", "vllm"): raise KeyError
      return value
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  @property
  def timeout(self) -> int:
    try: return int(self._metadata.json.struct_value.fields["timeout"].number_value)
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  @property
  def model_id(self) -> str:
    try: return self._metadata.json.struct_value.fields["model_id"].string_value
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  @property
  def configuration(self) -> dict[str, t.Any]:
    try: return orjson.loads(self._metadata.json.struct_value.fields["configuration"].string_value)
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  @property
  def supports_embeddings(self) -> bool:
    try: return self._metadata.json.struct_value.fields["supports_embeddings"].bool_value
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  @property
  def supports_hf_agent(self) -> bool:
    try: return self._metadata.json.struct_value.fields["supports_hf_agent"].bool_value
    except KeyError: raise RuntimeError("Malformed service endpoint. (Possible malicious)") from None
  def postprocess(self, result: Response | dict[str, t.Any]) -> openllm.GenerationOutput:
    from google.protobuf.json_format import MessageToDict
    if isinstance(result, dict): return openllm.GenerationOutput(**result)
    return openllm.GenerationOutput(**MessageToDict(result.json, preserving_proto_field_name=True))

class AsyncGrpcClient(BaseAsyncClient["Response"], client_type="grpc"):
  def __init__(self, address: str, timeout: int = 30):
    self._host, self._port = address.split(":")
    super().__init__(address, timeout)
  async def health(self) -> health_pb2.HealthCheckResponse: return await self._cached.health("bentoml.grpc.v1.BentoService")
