import logging
from typing import Optional

from opentelemetry import context as context_api
from opentelemetry.instrumentation.utils import _SUPPRESS_INSTRUMENTATION_KEY
from opentelemetry.trace.status import Status, StatusCode

from openllmtelemetry.guardrails import GuardrailsApi
from openllmtelemetry.guardrails.handlers import async_wrapper, sync_wrapper
from openllmtelemetry.instrumentation.openai.shared import (
    _set_request_attributes,
    _set_response_attributes,
    _set_span_attribute,
    is_streaming_response,
    model_as_dict,
    should_send_prompts,
)
from openllmtelemetry.instrumentation.openai.utils import (
    _with_tracer_wrapper,
    is_openai_v1,
)
from openllmtelemetry.semantic_conventions.gen_ai import LLMRequestTypeValues, SpanAttributes

SPAN_NAME = "openai.completion"
LLM_REQUEST_TYPE = LLMRequestTypeValues.COMPLETION

logger = logging.getLogger(__name__)


def create_prompt_provider(kwargs):
    def prompt_provider():
        return kwargs.get("prompt")

    return prompt_provider


@_with_tracer_wrapper
def completion_wrapper(tracer, guardrails_api: Optional[GuardrailsApi], wrapped, instance, args, kwargs):
    if context_api.get_value(_SUPPRESS_INSTRUMENTATION_KEY):
        return wrapped(*args, **kwargs)

    prompt_provider = create_prompt_provider(kwargs)

    def call_llm(span):
        r = wrapped(*args, **kwargs)
        if not kwargs.get("stream"):
            _handle_response(r, span)
            if is_openai_v1():
                response_dict = model_as_dict(r)
            else:
                response_dict = r

            _set_response_attributes(response_dict, span)
        return r

    def prompt_attributes_setter(span):
        _set_request_attributes(span, kwargs, instance=instance)

    def response_extractor(r):
        if is_openai_v1():
            response_dict = model_as_dict(r)
        else:
            response_dict = r
        return response_dict["choices"][0]["text"]

    return sync_wrapper(
        tracer, guardrails_api, prompt_provider, call_llm, response_extractor, prompt_attributes_setter, LLMRequestTypeValues.COMPLETION
    )


@_with_tracer_wrapper
async def acompletion_wrapper(tracer, guardrails_api: Optional[GuardrailsApi], wrapped, instance, args, kwargs):
    if context_api.get_value(_SUPPRESS_INSTRUMENTATION_KEY):
        return wrapped(*args, **kwargs)

    prompt_provider = create_prompt_provider(kwargs)

    async def call_llm(span):
        r = await wrapped(*args, **kwargs)
        if not kwargs.get("stream"):
            _handle_response(r, span)
        return r

    def prompt_attributes_setter(span):
        _set_request_attributes(span, kwargs, instance=instance)

    def response_extractor(r):
        if is_openai_v1():
            response_dict = model_as_dict(r)
        else:
            response_dict = r
        return response_dict["choices"][0]["text"]

    return async_wrapper(
        tracer,
        guardrails_api,  # guardrails_client,
        prompt_provider,
        call_llm,
        response_extractor,
        kwargs,
        prompt_attributes_setter,
        _build_from_streaming_response,
        is_streaming_response,
        LLMRequestTypeValues.COMPLETION,
    )


def _handle_response(response, span):
    if is_openai_v1():
        response_dict = model_as_dict(response)
    else:
        response_dict = response

    _set_response_attributes(response_dict, span)

    if should_send_prompts():
        _set_completions(span, response_dict.get("choices"))


def _set_prompts(span, prompt):
    if not span.is_recording() or not prompt:
        return

    try:
        _set_span_attribute(
            span,
            f"{SpanAttributes.LLM_PROMPTS}.0.user",
            prompt[0] if isinstance(prompt, list) else prompt,
        )
    except Exception as ex:  # pylint: disable=broad-except
        logger.warning("Failed to set prompts for openai span, error: %s", str(ex))


def _set_completions(span, choices):
    if not span.is_recording() or not choices:
        return

    try:
        for choice in choices:
            index = choice.get("index")
            prefix = f"{SpanAttributes.LLM_COMPLETIONS}.{index}"
            _set_span_attribute(span, f"{prefix}.finish_reason", choice.get("finish_reason"))
            _set_span_attribute(span, f"{prefix}.content", choice.get("text"))
    except Exception as e:
        logger.warning("Failed to set completion attributes, error: %s", str(e))


def _build_from_streaming_response(span, response):
    complete_response = {"choices": [], "model": ""}
    for item in response:
        item_to_yield = item
        if is_openai_v1():
            item = model_as_dict(item)

        for choice in item.get("choices"):
            index = choice.get("index")
            if len(complete_response.get("choices")) <= index:
                complete_response["choices"].append({"index": index, "text": ""})
            complete_choice = complete_response.get("choices")[index]
            if choice.get("finish_reason"):
                complete_choice["finish_reason"] = choice.get("finish_reason")

            complete_choice["text"] += choice.get("text")

        yield item_to_yield

    _set_response_attributes(complete_response, span)

    if should_send_prompts():
        _set_completions(span, complete_response.get("choices"))

    span.set_status(Status(StatusCode.OK))
    span.end()

import datetime
import re
import shutil
import typing

import pyaml
import questionary
import typer

from openllm.analytic import OpenLLMTyper
from openllm.common import INTERACTIVE, REPO_DIR, VERBOSE_LEVEL, RepoInfo, load_config, output, save_config

UPDATE_INTERVAL = datetime.timedelta(days=3)

app = OpenLLMTyper(help='manage repos')


@app.command(name='list', help='list available repo')
def list_repo(verbose: bool = False):
    if verbose:
        VERBOSE_LEVEL.set(20)
    config = load_config()
    pyaml.pprint(
        [parse_repo_url(repo, name) for name, repo in config.repos.items()], sort_dicts=False, sort_keys=False
    )


@app.command(help='remove given repo')
def remove(name: str):
    config = load_config()
    if name not in config.repos:
        output(f'Repo {name} does not exist', style='red')
        return

    del config.repos[name]
    save_config(config)
    output(f'Repo {name} removed', style='green')


def _complete_alias(repo_name: str):
    from openllm.model import list_bento

    for bento in list_bento(repo_name=repo_name):
        alias = bento.labels.get('openllm_alias', '').strip()
        if alias:
            for a in alias.split(','):
                with open(bento.path.parent / a, 'w') as f:
                    f.write(bento.version)


def _clone_repo(repo: RepoInfo):
    """
    clone the repo to local, use `git` command if possible, otherwise use dulwich
    """
    import subprocess

    try:
        subprocess.run(['git', 'clone', '--depth=1', '-b', repo.branch, repo.url, str(repo.path)], check=True)
    except (subprocess.CalledProcessError, FileNotFoundError):
        import dulwich
        import dulwich.porcelain

        dulwich.porcelain.clone(repo.url, str(repo.path), checkout=True, depth=1, branch=repo.branch)


@app.command(help='update default repo')
def update():
    config = load_config()
    repos_in_use = set()
    for repo_name, repo in config.repos.items():
        repo = parse_repo_url(repo, repo_name)
        repos_in_use.add((repo.server, repo.owner, repo.repo, repo.branch))
        if repo.path.exists():
            shutil.rmtree(repo.path, ignore_errors=True)
        repo.path.parent.mkdir(parents=True, exist_ok=True)
        try:
            _clone_repo(repo)
            output('')
            output(f'Repo `{repo.name}` updated', style='green')
        except Exception as e:
            shutil.rmtree(repo.path, ignore_errors=True)
            output(f'Failed to clone repo {repo.name}', style='red')
            output(e)
    for c in REPO_DIR.glob('*/*/*/*'):
        repo_spec = tuple(c.parts[-4:])
        if repo_spec not in repos_in_use:
            shutil.rmtree(c, ignore_errors=True)
            output(f'Removed unused repo cache {c}')
    with open(REPO_DIR / 'last_update', 'w') as f:
        f.write(datetime.datetime.now().isoformat())
    for repo_name in config.repos:
        _complete_alias(repo_name)


def ensure_repo_updated():
    last_update_file = REPO_DIR / 'last_update'
    if not last_update_file.exists():
        if INTERACTIVE.get():
            choice = questionary.confirm(
                'The repo cache is never updated, do you want to update it to fetch the latest model list?'
            ).ask()
            if choice:
                update()
            return
        else:
            output(
                'The repo cache is never updated, please run `openllm repo update` to fetch the latest model list',
                style='red',
            )
            raise typer.Exit(1)
    last_update = datetime.datetime.fromisoformat(last_update_file.read_text().strip())
    if datetime.datetime.now() - last_update > UPDATE_INTERVAL:
        if INTERACTIVE.get():
            choice = questionary.confirm(
                'The repo cache is outdated, do you want to update it to fetch the latest model list?'
            ).ask()
            if choice:
                update()
        else:
            output(
                'The repo cache is outdated, please run `openllm repo update` to fetch the latest model list',
                style='yellow',
            )


GIT_HTTP_RE = re.compile(
    r'(?P<schema>git|ssh|http|https):\/\/(?P<server>[\.\w\d\-]+)\/(?P<owner>[\w\d\-]+)\/(?P<repo>[\w\d\-\_\.]+)(@(?P<branch>.+))?(\/)?$'
)
GIT_SSH_RE = re.compile(
    r'git@(?P<server>[\.\w\d-]+):(?P<owner>[\w\d\-]+)\/(?P<repo>[\w\d\-\_\.]+)(@(?P<branch>.+))?(\/)?$'
)


def parse_repo_url(repo_url: str, repo_name: typing.Optional[str] = None) -> RepoInfo:
    """
    parse the git repo url to server, owner, repo name, branch
    >>> parse_repo_url('https://github.com/bentoml/bentovllm@main')
    ('github.com', 'bentoml', 'bentovllm', 'main')

    >>> parse_repo_url('https://github.com/bentoml/bentovllm.git@main')
    ('github.com', 'bentoml', 'bentovllm', 'main')

    >>> parse_repo_url('https://github.com/bentoml/bentovllm')
    ('github.com', 'bentoml', 'bentovllm', 'main')

    >>> parse_repo_url('git@github.com:bentoml/openllm-models.git')
    ('github.com', 'bentoml', 'openllm-models', 'main')
    """
    match = GIT_HTTP_RE.match(repo_url)
    if match:
        schema = match.group('schema')
    else:
        match = GIT_SSH_RE.match(repo_url)
        if not match:
            raise ValueError(f'Invalid git repo url: {repo_url}')
        schema = None

    if match.group('branch') is not None:
        repo_url = repo_url[: match.start('branch') - 1]

    server = match.group('server')
    owner = match.group('owner')
    repo = match.group('repo')
    if repo.endswith('.git'):
        repo = repo[:-4]
    branch = match.group('branch') or 'main'

    if schema is not None:
        repo_url = f'{schema}://{server}/{owner}/{repo}'
    else:
        repo_url = f'git@{server}:{owner}/{repo}'

    path = REPO_DIR / server / owner / repo / branch
    return RepoInfo(
        name=repo if repo_name is None else repo_name,
        url=repo_url,
        server=server,
        owner=owner,
        repo=repo,
        branch=branch,
        path=path,
    )


@app.command(help='add new repo')
def add(name: str, repo: str):
    name = name.lower()
    if not name.isidentifier():
        output(f'Invalid repo name: {name}, should only contain letters, numbers and underscores', style='red')
        return

    try:
        parse_repo_url(repo)
    except ValueError:
        output(f'Invalid repo url: {repo}', style='red')
        return

    config = load_config()
    if name in config.repos:
        override = questionary.confirm(f'Repo {name} already exists({config.repos[name]}), override?').ask()
        if not override:
            return

    config.repos[name] = repo
    save_config(config)
    output(f'Repo {name} added', style='green')


@app.command(help='get default repo path')
def default():
    output((info := parse_repo_url(load_config().repos['default'], 'default')).path)
    return info.path


if __name__ == '__main__':
    app()

class OpenLLMAPI(LLM):
    """OpenLLM Client interface. This is useful when interacting with a remote OpenLLM server."""

    address: Optional[str] = Field(
        description="OpenLLM server address. This could either be set here or via OPENLLM_ENDPOINT"
    )
    timeout: int = Field(description="Timeout for sending requests.")
    max_retries: int = Field(description="Maximum number of retries.")
    api_version: Literal["v1"] = Field(description="OpenLLM Server API version.")

    if TYPE_CHECKING:
        try:
            from openllm_client import AsyncHTTPClient, HTTPClient

            _sync_client: HTTPClient
            _async_client: AsyncHTTPClient
        except ImportError:
            _sync_client: Any  # type: ignore[no-redef]
            _async_client: Any  # type: ignore[no-redef]
    else:
        _sync_client: Any = PrivateAttr()
        _async_client: Any = PrivateAttr()

    def __init__(
        self,
        address: Optional[str] = None,
        timeout: int = 30,
        max_retries: int = 2,
        api_version: Literal["v1"] = "v1",
        **kwargs: Any,
    ):
        try:
            from openllm_client import AsyncHTTPClient, HTTPClient
        except ImportError:
            raise ImportError(
                f'"{type(self).__name__}" requires "openllm-client". Make sure to install with `pip install openllm-client`'
            )
        super().__init__(
            address=address,
            timeout=timeout,
            max_retries=max_retries,
            api_version=api_version,
            **kwargs,
        )
        self._sync_client = HTTPClient(
            address=address,
            timeout=timeout,
            max_retries=max_retries,
            api_version=api_version,
        )
        self._async_client = AsyncHTTPClient(
            address=address,
            timeout=timeout,
            max_retries=max_retries,
            api_version=api_version,
        )

    @classmethod
    def class_name(cls) -> str:
        return "OpenLLM_Client"

    @property
    def _server_metadata(self) -> "Metadata":
        return self._sync_client._metadata

    @property
    def _server_config(self) -> Dict[str, Any]:
        return self._sync_client._config

    @property
    def metadata(self) -> LLMMetadata:
        return LLMMetadata(
            num_output=self._server_config["max_new_tokens"],
            model_name=self._server_metadata.model_id.replace("/", "--"),
        )

    def _convert_messages_to_prompt(self, messages: Sequence[ChatMessage]) -> str:
        return self._sync_client.helpers.messages(
            messages=[
                {"role": message.role, "content": message.content}
                for message in messages
            ],
            add_generation_prompt=True,
        )

    async def _async_messages_to_prompt(self, messages: Sequence[ChatMessage]) -> str:
        return await self._async_client.helpers.messages(
            messages=[
                {"role": message.role, "content": message.content}
                for message in messages
            ],
            add_generation_prompt=True,
        )

    @llm_completion_callback()
    def complete(self, prompt: str, **kwargs: Any) -> CompletionResponse:
        response = self._sync_client.generate(prompt, **kwargs)
        return CompletionResponse(
            text=response.outputs[0].text,
            raw=response.model_dump(),
            additional_kwargs={
                "prompt_token_ids": response.prompt_token_ids,
                "prompt_logprobs": response.prompt_logprobs,
                "finished": response.finished,
                "outputs": {
                    "token_ids": response.outputs[0].token_ids,
                    "cumulative_logprob": response.outputs[0].cumulative_logprob,
                    "logprobs": response.outputs[0].logprobs,
                    "finish_reason": response.outputs[0].finish_reason,
                },
            },
        )

    @llm_completion_callback()
    def stream_complete(self, prompt: str, **kwargs: Any) -> CompletionResponseGen:
        for response_chunk in self._sync_client.generate_stream(prompt, **kwargs):
            yield CompletionResponse(
                text=response_chunk.text,
                delta=response_chunk.text,
                raw=response_chunk.model_dump(),
                additional_kwargs={"token_ids": response_chunk.token_ids},
            )

    @llm_chat_callback()
    def chat(self, messages: Sequence[ChatMessage], **kwargs: Any) -> ChatResponse:
        return completion_response_to_chat_response(
            self.complete(self._convert_messages_to_prompt(messages), **kwargs)
        )

    @llm_chat_callback()
    def stream_chat(
        self, messages: Sequence[ChatMessage], **kwargs: Any
    ) -> ChatResponseGen:
        for response_chunk in self.stream_complete(
            self._convert_messages_to_prompt(messages), **kwargs
        ):
            yield completion_response_to_chat_response(response_chunk)

    @llm_completion_callback()
    async def acomplete(self, prompt: str, **kwargs: Any) -> CompletionResponse:
        response = await self._async_client.generate(prompt, **kwargs)
        return CompletionResponse(
            text=response.outputs[0].text,
            raw=response.model_dump(),
            additional_kwargs={
                "prompt_token_ids": response.prompt_token_ids,
                "prompt_logprobs": response.prompt_logprobs,
                "finished": response.finished,
                "outputs": {
                    "token_ids": response.outputs[0].token_ids,
                    "cumulative_logprob": response.outputs[0].cumulative_logprob,
                    "logprobs": response.outputs[0].logprobs,
                    "finish_reason": response.outputs[0].finish_reason,
                },
            },
        )

    @llm_completion_callback()
    async def astream_complete(
        self, prompt: str, **kwargs: Any
    ) -> CompletionResponseAsyncGen:
        async for response_chunk in self._async_client.generate_stream(
            prompt, **kwargs
        ):
            yield CompletionResponse(
                text=response_chunk.text,
                delta=response_chunk.text,
                raw=response_chunk.model_dump(),
                additional_kwargs={"token_ids": response_chunk.token_ids},
            )

    @llm_chat_callback()
    async def achat(
        self, messages: Sequence[ChatMessage], **kwargs: Any
    ) -> ChatResponse:
        return completion_response_to_chat_response(
            await self.acomplete(
                await self._async_messages_to_prompt(messages), **kwargs
            )
        )

    @llm_chat_callback()
    async def astream_chat(
        self, messages: Sequence[ChatMessage], **kwargs: Any
    ) -> ChatResponseAsyncGen:
        async for response_chunk in self.astream_complete(
            await self._async_messages_to_prompt(messages), **kwargs
        ):
            yield completion_response_to_chat_response(response_chunk)

from __future__ import annotations

import json, os, pathlib, shutil, subprocess, typing
import typer

from openllm.analytic import OpenLLMTyper
from openllm.accelerator_spec import ACCELERATOR_SPECS
from openllm.common import BentoInfo, DeploymentTarget, EnvVars, output, run_command, INTERACTIVE

app = OpenLLMTyper()


def resolve_cloud_config() -> pathlib.Path:
  env = os.environ.get('BENTOML_HOME')
  if env is not None:
    return pathlib.Path(env) / '.yatai.yaml'
  return pathlib.Path.home() / 'bentoml' / '.yatai.yaml'


def _get_deploy_cmd(
  bento: BentoInfo,
  target: typing.Optional[DeploymentTarget] = None,
  cli_envs: typing.Optional[list[str]] = None,
  context: typing.Optional[str] = None,
  cli_args: typing.Optional[list[str]] = None,
) -> tuple[list[str], EnvVars]:
  cmd = ['bentoml', 'deploy', bento.bentoml_tag]
  if cli_args:
    for arg in cli_args:
      cmd += ['--arg', arg]

  env = EnvVars({'BENTOML_HOME': f'{bento.repo.path}/bentoml'})

  # Process CLI env vars first to determine overrides
  explicit_envs: dict[str, str] = {}
  if cli_envs:
    for env_var in cli_envs:
      if '=' in env_var:
        name, value = env_var.split('=', 1)
        explicit_envs[name] = value
      else:
        name = env_var
        value = typing.cast(str, os.environ.get(name))
        if value is None:
          output(
            f"Environment variable '{name}' specified via --env but not found in the current environment.",
            style='red',
          )
          raise typer.Exit(1)
        explicit_envs[name] = value

  # Process envs defined in bento.yaml, skipping those overridden by CLI
  required_envs = bento.bento_yaml.get('envs', [])

  all_required_env_names = [env['name'] for env in required_envs if 'name' in env]
  required_env_names = [
    env['name']
    for env in required_envs
    if 'name' in env
    and env['name'] not in explicit_envs
    and not env.get('value')
    and env['name'] not in os.environ
  ]
  if required_env_names:
    output(
      f'This model requires the following environment variables to run (unless overridden via --env): {required_env_names!r}',
      style='green',
    )

  for env_info in required_envs:
    name = typing.cast(str, env_info.get('name'))
    if not name or name in explicit_envs or env_info.get('value', ''):
      continue

    if os.environ.get(name):
      default = os.environ[name]
    elif 'value' in env_info:
      default = env_info['value']
    else:
      default = ''

    if INTERACTIVE.get():
      import questionary

      value = questionary.text(f'{name}: (from bento.yaml)', default=default).ask()
    else:
      if default == '':
        output(
          f'Environment variable {name} (from bento.yaml) is required but not provided', style='red'
        )
        raise typer.Exit(1)
      else:
        value = default

    if value is None:
      raise typer.Exit(1)
    cmd += ['--env', f'{name}={value}']

  # Add any required envs from os.environ that haven't been handled yet
  for name in all_required_env_names:
    if name in os.environ:
      cmd += ['--env', f'{name}={os.environ.get(name)}']

  # Add explicitly provided env vars from CLI
  for name, value in explicit_envs.items():
    cmd += ['--env', f'{name}={value}']

  if target:
    cmd += ['--instance-type', target.name]

  if context:
    cmd += ['--context', context]

  base_config = resolve_cloud_config()
  if not base_config.exists():
    raise Exception('Cannot find cloud config.')
  # remove before copy
  if (bento.repo.path / 'bentoml' / '.yatai.yaml').exists():
    (bento.repo.path / 'bentoml' / '.yatai.yaml').unlink()
  shutil.copy(base_config, bento.repo.path / 'bentoml' / '.yatai.yaml')

  return cmd, env


def get_current_context() -> str | None:
  cmd = ['bentoml', 'cloud', 'current-context']
  try:
    result = subprocess.check_output(cmd, stderr=subprocess.DEVNULL)
    return typing.cast(str, json.loads(result)['name'])
  except subprocess.CalledProcessError:
    return None


def ensure_cloud_context() -> None:
  import questionary

  cmd = ['bentoml', 'cloud', 'current-context']
  try:
    result = subprocess.check_output(cmd, stderr=subprocess.DEVNULL)
    context = json.loads(result)
    output(f'  bentoml already logged in: {context["endpoint"]}', style='green', level=20)
  except subprocess.CalledProcessError:
    output('  bentoml not logged in', style='red')
    if not INTERACTIVE.get():
      output('\n  get bentoml logged in by:')
      output('    $ bentoml cloud login', style='orange')
      output('')
      output(
        """  * you may need to visit https://cloud.bentoml.com to get an account. you can also bring your own bentoml cluster (BYOC) to your team from https://bentoml.com/contact""",
        style='yellow',
      )
      raise typer.Exit(1)
    else:
      action = questionary.select(
        'Choose an action:',
        choices=['I have a BentoCloud account', 'get an account in two minutes'],
      ).ask()
      if action is None:
        raise typer.Exit(1)
      elif action == 'get an account in two minutes':
        output('Please visit https://cloud.bentoml.com to get your token', style='yellow')
      endpoint = questionary.text(
        'Enter the endpoint: (similar to https://my-org.cloud.bentoml.com)'
      ).ask()
      if endpoint is None:
        raise typer.Exit(1)
      token = questionary.text('Enter your token: (similar to cniluaxxxxxxxx)').ask()
      if token is None:
        raise typer.Exit(1)
      cmd = ['bentoml', 'cloud', 'login', '--api-token', token, '--endpoint', endpoint]
      try:
        result = subprocess.check_output(cmd)
        output('  Logged in successfully', style='green')
      except subprocess.CalledProcessError:
        output('  Failed to login', style='red')
        raise typer.Exit(1)


def get_cloud_machine_spec(context: typing.Optional[str] = None) -> list[DeploymentTarget]:
  ensure_cloud_context()
  cmd = ['bentoml', 'deployment', 'list-instance-types', '-o', 'json']
  if context:
    cmd += ['--context', context]

  if context is None:
    context = get_current_context()

  try:
    result = subprocess.check_output(cmd, stderr=subprocess.DEVNULL)
    instance_types = json.loads(result)
    return [
      DeploymentTarget(
        source='cloud',
        name=it['name'],
        price=it['price'],
        platform='linux',
        accelerators=(
          [ACCELERATOR_SPECS[it['gpu_type']] for _ in range(int(it['gpu']))]
          if it.get('gpu') and it['gpu_type'] in ACCELERATOR_SPECS
          else []
        ),
      )
      for it in instance_types
    ]
  except (subprocess.CalledProcessError, json.JSONDecodeError):
    output(
      f'Failed to get cloud instance types{"" if context is None else f" for context {context}"}',
      style='red',
    )
    return []


def deploy(
  bento: BentoInfo,
  target: DeploymentTarget,
  cli_envs: typing.Optional[list[str]] = None,
  context: typing.Optional[str] = None,
  cli_args: typing.Optional[list[str]] = None,
  interactive: bool = False,
) -> None:
  INTERACTIVE.set(interactive)
  ensure_cloud_context()
  cmd, env = _get_deploy_cmd(bento, target, cli_envs=cli_envs, context=context, cli_args=cli_args)
  run_command(cmd, env=env, cwd=None)

from __future__ import annotations

import datetime, subprocess, re, shutil, typing, os, pathlib
import pyaml, questionary, typer

from openllm.analytic import OpenLLMTyper
from openllm.common import (
  INTERACTIVE,
  REPO_DIR,
  VERBOSE_LEVEL,
  RepoInfo,
  load_config,
  output,
  save_config,
)

UPDATE_INTERVAL = datetime.timedelta(days=3)
TEST_REPO = os.getenv('OPENLLM_TEST_REPO', None)  # for testing


app = OpenLLMTyper(help='manage repos')


@app.command(name='list', help='list available repo')
def cmd_list(verbose: bool = False) -> None:
  if verbose:
    VERBOSE_LEVEL.set(20)
  pyaml.pprint(list_repo(), sort_dicts=False, sort_keys=False)


@app.command(name='remove', help='remove given repo')
def cmd_remove(name: str) -> None:
  if TEST_REPO:
    return
  config = load_config()
  if name not in config.repos:
    output(f'Repo {name} does not exist', style='red')
    return

  del config.repos[name]
  save_config(config)
  output(f'Repo {name} removed', style='green')


@app.command(name='update', help='update default repo')
def cmd_update() -> None:
  if TEST_REPO:
    return

  repos_in_use = set()
  for repo in list_repo():
    # Show simplified output if not in verbose mode
    if VERBOSE_LEVEL.get() <= 0:
      output(f'updating repo {repo.name}', style='green')

    repos_in_use.add((repo.server, repo.owner, repo.repo, repo.branch))
    if repo.path.exists():
      shutil.rmtree(repo.path, ignore_errors=True)
    repo.path.parent.mkdir(parents=True, exist_ok=True)
    try:
      _clone_repo(repo)
      if VERBOSE_LEVEL.get() > 0:
        output('')
        output(f'Repo `{repo.name}` updated', style='green')
    except Exception as e:
      shutil.rmtree(repo.path, ignore_errors=True)
      if VERBOSE_LEVEL.get() > 0:
        output(f'Failed to clone repo {repo.name}', style='red')
        output(e)
  for c in REPO_DIR.glob('*/*/*/*'):
    repo_spec = tuple(c.parts[-4:])
    if repo_spec not in repos_in_use:
      shutil.rmtree(c, ignore_errors=True)
      if VERBOSE_LEVEL.get() > 0:
        output(f'Removed unused repo cache {c}')
  with open(REPO_DIR / 'last_update', 'w') as f:
    f.write(datetime.datetime.now().isoformat())
  for repo in list_repo():
    _complete_alias(repo.name)


@app.command(name='add', help='add new repo')
def cmd_add(name: str, repo: str) -> None:
  if TEST_REPO:
    return
  name = name.lower()
  if not name.isidentifier():
    output(
      f'Invalid repo name: {name}, should only contain letters, numbers and underscores',
      style='red',
    )
    return

  try:
    parse_repo_url(repo)
  except ValueError:
    output(f'Invalid repo url: {repo}', style='red')
    return

  config = load_config()
  if name in config.repos:
    override = questionary.confirm(
      f'Repo {name} already exists({config.repos[name]}), override?'
    ).ask()
    if not override:
      return

  config.repos[name] = repo
  save_config(config)
  output(f'Repo {name} added', style='green')


@app.command(name='default', help='get default repo path')
def default() -> typing.Optional[pathlib.Path]:
  if TEST_REPO:
    return None
  output((info := parse_repo_url(load_config().repos['default'], 'default')).path)
  return info.path


def list_repo(repo_name: typing.Optional[str] = None) -> typing.List[RepoInfo]:
  if TEST_REPO:
    return [
      RepoInfo(
        name='default',
        url='',
        server='test',
        owner='test',
        repo='test',
        branch='main',
        path=pathlib.Path(TEST_REPO),
      )
    ]
  config = load_config()
  repos = []
  for _repo_name, repo_url in config.repos.items():
    if repo_name is not None and _repo_name != repo_name:
      continue
    repo = parse_repo_url(repo_url, _repo_name)
    repos.append(repo)
  return repos


def _complete_alias(repo_name: str) -> None:
  from openllm.model import list_bento

  for bento in list_bento(repo_name=repo_name):
    alias = bento.labels.get('aliases', '').strip()
    if alias:
      for a in alias.split(','):
        with open(bento.path.parent / a, 'w') as f:
          f.write(bento.version)


def _clone_repo(repo: RepoInfo) -> None:
  try:
    # Suppress output if verbosity level is low
    if VERBOSE_LEVEL.get() <= 0:
      subprocess.run(
        ['git', 'clone', '--depth=1', '-b', repo.branch, repo.url, str(repo.path)],
        check=True,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
      )
    else:
      subprocess.run(
        ['git', 'clone', '--depth=1', '-b', repo.branch, repo.url, str(repo.path)], check=True
      )
  except (subprocess.CalledProcessError, FileNotFoundError):
    import dulwich
    import dulwich.porcelain

    # Dulwich doesn't have easy output suppression, but we rarely get here
    dulwich.porcelain.clone(repo.url, str(repo.path), checkout=True, depth=1, branch=repo.branch)


def ensure_repo_updated() -> None:
  if TEST_REPO:
    return
  last_update_file = REPO_DIR / 'last_update'
  if not last_update_file.exists():
    if INTERACTIVE.get():
      choice = questionary.confirm(
        'The repo cache is never updated, do you want to update it to fetch the latest model list?'
      ).ask()
      if choice:
        cmd_update()
      return
    else:
      output(
        'The repo cache is never updated, please run `openllm repo update` to fetch the latest model list',
        style='red',
      )
      raise typer.Exit(1)
  last_update = datetime.datetime.fromisoformat(last_update_file.read_text().strip())
  if datetime.datetime.now() - last_update > UPDATE_INTERVAL:
    if INTERACTIVE.get():
      choice = questionary.confirm(
        'The repo cache is outdated, do you want to update it to fetch the latest model list?'
      ).ask()
      if choice:
        cmd_update()
    else:
      output(
        'The repo cache is outdated, please run `openllm repo update` to fetch the latest model list',
        style='yellow',
      )


GIT_HTTP_RE = re.compile(
  r'(?P<schema>git|ssh|http|https):\/\/(?P<server>[\.\w\d\-]+)\/(?P<owner>[\w\d\-]+)\/(?P<repo>[\w\d\-\_\.]+)(@(?P<branch>.+))?(\/)?$'
)
GIT_SSH_RE = re.compile(
  r'git@(?P<server>[\.\w\d-]+):(?P<owner>[\w\d\-]+)\/(?P<repo>[\w\d\-\_\.]+)(@(?P<branch>.+))?(\/)?$'
)


def parse_repo_url(repo_url: str, repo_name: typing.Optional[str] = None) -> RepoInfo:
  """
  parse the git repo url to server, owner, repo name, branch
  >>> parse_repo_url('https://github.com/bentoml/bentovllm@main')
  ('github.com', 'bentoml', 'bentovllm', 'main')

  >>> parse_repo_url('https://github.com/bentoml/bentovllm.git@main')
  ('github.com', 'bentoml', 'bentovllm', 'main')

  >>> parse_repo_url('https://github.com/bentoml/bentovllm')
  ('github.com', 'bentoml', 'bentovllm', 'main')

  >>> parse_repo_url('git@github.com:bentoml/openllm-models.git')
  ('github.com', 'bentoml', 'openllm-models', 'main')
  """
  match = GIT_HTTP_RE.match(repo_url)
  if match:
    schema = match.group('schema')
  else:
    match = GIT_SSH_RE.match(repo_url)
    if not match:
      raise ValueError(f'Invalid git repo url: {repo_url}')
    schema = None

  if match.group('branch') is not None:
    repo_url = repo_url[: match.start('branch') - 1]

  server = match.group('server')
  owner = match.group('owner')
  repo = match.group('repo')
  if repo.endswith('.git'):
    repo = repo[:-4]
  branch = match.group('branch') or 'main'

  if schema is not None:
    repo_url = f'{schema}://{server}/{owner}/{repo}'
  else:
    repo_url = f'git@{server}:{owner}/{repo}'

  path = REPO_DIR / server / owner / repo / branch
  return RepoInfo(
    name=repo if repo_name is None else repo_name,
    url=repo_url,
    server=server,
    owner=owner,
    repo=repo,
    branch=branch,
    path=path,
  )


if __name__ == '__main__':
  app()

from __future__ import annotations
import asyncio, contextlib, functools, logging, sys, time, typing as t
from abc import ABC, abstractmethod
import attr, docker, docker.errors, docker.types, orjson, pytest, openllm
from syrupy.extensions.json import JSONSnapshotExtension
from openllm._llm import normalise_model_name
from openllm._typing_compat import DictStrAny, ListAny

logger = logging.getLogger(__name__)

if t.TYPE_CHECKING:
  import subprocess
  from syrupy.assertion import SnapshotAssertion
  from syrupy.types import PropertyFilter, PropertyMatcher, SerializableData, SerializedData
  from openllm._configuration import GenerationConfig
  from openllm.client import BaseAsyncClient

class ResponseComparator(JSONSnapshotExtension):
  def serialize(self, data: SerializableData, *, exclude: PropertyFilter | None = None, matcher: PropertyMatcher | None = None,) -> SerializedData:
    if openllm.utils.LazyType(ListAny).isinstance(data):
      data = [d.unmarshaled for d in data]
    else:
      data = data.unmarshaled
    data = self._filter(data=data, depth=0, path=(), exclude=exclude, matcher=matcher)
    return orjson.dumps(data, option=orjson.OPT_INDENT_2 | orjson.OPT_SORT_KEYS).decode()

  def matches(self, *, serialized_data: SerializableData, snapshot_data: SerializableData) -> bool:
    def convert_data(data: SerializableData) -> openllm.GenerationOutput | t.Sequence[openllm.GenerationOutput]:
      try:
        data = orjson.loads(data)
      except orjson.JSONDecodeError as err:
        raise ValueError(f"Failed to decode JSON data: {data}") from err
      if openllm.utils.LazyType(DictStrAny).isinstance(data):
        return openllm.GenerationOutput(**data)
      elif openllm.utils.LazyType(ListAny).isinstance(data):
        return [openllm.GenerationOutput(**d) for d in data]
      else:
        raise NotImplementedError(f"Data {data} has unsupported type.")

    serialized_data = convert_data(serialized_data)
    snapshot_data = convert_data(snapshot_data)

    if openllm.utils.LazyType(ListAny).isinstance(serialized_data):
      serialized_data = [serialized_data]
    if openllm.utils.LazyType(ListAny).isinstance(snapshot_data):
      snapshot_data = [snapshot_data]

    def eq_config(s: GenerationConfig, t: GenerationConfig) -> bool:
      return s == t

    def eq_output(s: openllm.GenerationOutput, t: openllm.GenerationOutput) -> bool:
      return (len(s.responses) == len(t.responses) and all([_s == _t for _s, _t in zip(s.responses, t.responses)]) and eq_config(s.marshaled_config, t.marshaled_config))

    return len(serialized_data) == len(snapshot_data) and all([eq_output(s, t) for s, t in zip(serialized_data, snapshot_data)])

@pytest.fixture()
def response_snapshot(snapshot: SnapshotAssertion):
  return snapshot.use_extension(ResponseComparator)

@attr.define(init=False)
class _Handle(ABC):
  port: int
  deployment_mode: t.Literal["container", "local"]

  client: BaseAsyncClient[t.Any] = attr.field(init=False)

  if t.TYPE_CHECKING:

    def __attrs_init__(self, *args: t.Any, **attrs: t.Any):
      ...

  def __attrs_post_init__(self):
    self.client = openllm.client.AsyncHTTPClient(f"http://localhost:{self.port}")

  @abstractmethod
  def status(self) -> bool:
    raise NotImplementedError

  async def health(self, timeout: int = 240):
    start_time = time.time()
    while time.time() - start_time < timeout:
      if not self.status():
        raise RuntimeError(f"Failed to initialise {self.__class__.__name__}")
      await self.client.health()
      try:
        await self.client.query("sanity")
        return
      except Exception:
        time.sleep(1)
    raise RuntimeError(f"Handle failed to initialise within {timeout} seconds.")

@attr.define(init=False)
class LocalHandle(_Handle):
  process: subprocess.Popen[bytes]

  def __init__(self, process: subprocess.Popen[bytes], port: int, deployment_mode: t.Literal["container", "local"],):
    self.__attrs_init__(port, deployment_mode, process)

  def status(self) -> bool:
    return self.process.poll() is None

class HandleProtocol(t.Protocol):
  @contextlib.contextmanager
  def __call__(*, model: str, model_id: str, image_tag: str, quantize: t.AnyStr | None = None,) -> t.Generator[_Handle, None, None]:
    ...

@attr.define(init=False)
class DockerHandle(_Handle):
  container_name: str
  docker_client: docker.DockerClient

  def __init__(self, docker_client: docker.DockerClient, container_name: str, port: int, deployment_mode: t.Literal["container", "local"],):
    self.__attrs_init__(port, deployment_mode, container_name, docker_client)

  def status(self) -> bool:
    container = self.docker_client.containers.get(self.container_name)
    return container.status in ["running", "created"]

@contextlib.contextmanager
def _local_handle(model: str, model_id: str, image_tag: str, deployment_mode: t.Literal["container", "local"], quantize: t.Literal["int8", "int4", "gptq"] | None = None, *, _serve_grpc: bool = False,):
  with openllm.utils.reserve_free_port() as port:
    pass

  if not _serve_grpc:
    proc = openllm.start(model, model_id=model_id, quantize=quantize, additional_args=["--port", str(port)], __test__=True)
  else:
    proc = openllm.start_grpc(model, model_id=model_id, quantize=quantize, additional_args=["--port", str(port)], __test__=True)

  yield LocalHandle(proc, port, deployment_mode)
  proc.terminate()
  proc.wait(60)

  process_output = proc.stdout.read()
  print(process_output, file=sys.stderr)

  proc.stdout.close()
  if proc.stderr:
    proc.stderr.close()

@contextlib.contextmanager
def _container_handle(model: str, model_id: str, image_tag: str, deployment_mode: t.Literal["container", "local"], quantize: t.Literal["int8", "int4", "gptq"] | None = None, *, _serve_grpc: bool = False,):
  envvar = openllm.utils.EnvVarMixin(model)

  with openllm.utils.reserve_free_port() as port, openllm.utils.reserve_free_port() as prom_port:
    pass
  container_name = f"openllm-{model}-{normalise_model_name(model_id)}".replace("-", "_")
  client = docker.from_env()
  try:
    container = client.containers.get(container_name)
    container.stop()
    container.wait()
    container.remove()
  except docker.errors.NotFound:
    pass

  args = ["serve" if not _serve_grpc else "serve-grpc"]

  env: DictStrAny = {}

  if quantize is not None:
    env[envvar.quantize] = quantize

  gpus = openllm.utils.device_count() or -1
  devs = [docker.types.DeviceRequest(count=gpus, capabilities=[["gpu"]])] if gpus > 0 else None

  container = client.containers.run(image_tag, command=args, name=container_name, environment=env, auto_remove=False, detach=True, device_requests=devs, ports={"3000/tcp": port, "3001/tcp": prom_port},)

  yield DockerHandle(client, container.name, port, deployment_mode)

  try:
    container.stop()
    container.wait()
  except docker.errors.NotFound:
    pass

  container_output = container.logs().decode("utf-8")
  print(container_output, file=sys.stderr)

  container.remove()

@pytest.fixture(scope="session", autouse=True)
def clean_context() -> t.Generator[contextlib.ExitStack, None, None]:
  stack = contextlib.ExitStack()
  yield stack
  stack.close()

@pytest.fixture(scope="module")
def el() -> t.Generator[asyncio.AbstractEventLoop, None, None]:
  loop = asyncio.get_event_loop()
  yield loop
  loop.close()

@pytest.fixture(params=["container", "local"], scope="session")
def deployment_mode(request: pytest.FixtureRequest) -> str:
  return request.param

@pytest.fixture(scope="module")
def handler(el: asyncio.AbstractEventLoop, deployment_mode: t.Literal["container", "local"]):
  if deployment_mode == "container":
    return functools.partial(_container_handle, deployment_mode=deployment_mode)
  elif deployment_mode == "local":
    return functools.partial(_local_handle, deployment_mode=deployment_mode)
  else:
    raise ValueError(f"Unknown deployment mode: {deployment_mode}")

# mypy: disable-error-code="type-arg"
from __future__ import annotations
import importlib, inspect, logging, typing as t
from collections import OrderedDict
import inflection, openllm
from openllm.utils import ReprMixin

if t.TYPE_CHECKING:
  from openllm._typing_compat import LiteralString, LLMRunner
  import types
  from collections import _odict_items, _odict_keys, _odict_values

  from _typeshed import SupportsIter
  ConfigModelKeysView = _odict_keys[type[openllm.LLMConfig], type[openllm.LLM[t.Any, t.Any]]]
  ConfigModelValuesView = _odict_values[type[openllm.LLMConfig], type[openllm.LLM[t.Any, t.Any]]]
  ConfigModelItemsView = _odict_items[type[openllm.LLMConfig], type[openllm.LLM[t.Any, t.Any]]]

logger = logging.getLogger(__name__)

class BaseAutoLLMClass:
  _model_mapping: t.ClassVar[_LazyAutoMapping]
  def __init__(self, *args: t.Any, **attrs: t.Any): raise EnvironmentError(f"Cannot instantiate {self.__class__.__name__} directly. Please use '{self.__class__.__name__}.Runner(model_name)' instead.")
  @classmethod
  def for_model(cls, model: str, /, model_id: str | None = None, model_version: str | None = None, llm_config: openllm.LLMConfig | None = None, ensure_available: bool = False, **attrs: t.Any) -> openllm.LLM[t.Any, t.Any]:
    """The lower level API for creating a LLM instance.

    ```python
    >>> import openllm
    >>> llm = openllm.AutoLLM.for_model("flan-t5")
    ```
    """
    llm = cls.infer_class_from_name(model).from_pretrained(model_id=model_id, model_version=model_version, llm_config=llm_config, **attrs)
    if ensure_available: llm.ensure_model_id_exists()
    return llm
  @classmethod
  def create_runner(cls, model: str, model_id: str | None = None, **attrs: t.Any) -> LLMRunner[t.Any, t.Any]:
    """Create a LLM Runner for the given model name.

    Args:
    model: The model name to instantiate.
    model_id: The pretrained model name to instantiate.
    **attrs: Additional keyword arguments passed along to the specific configuration class.

    Returns:
    A LLM instance.
    """
    runner_kwargs_name = set(inspect.signature(openllm.LLM[t.Any, t.Any].to_runner).parameters)
    runner_attrs = {k: v for k, v in attrs.items() if k in runner_kwargs_name}
    for k in runner_attrs: del attrs[k]
    return cls.for_model(model, model_id=model_id, **attrs).to_runner(**runner_attrs)
  @classmethod
  def register(cls, config_class: type[openllm.LLMConfig], llm_class: type[openllm.LLM[t.Any, t.Any]]) -> None:
    """Register a new model for this class.

    Args:
    config_class: The configuration corresponding to the model to register.
    llm_class: The runnable to register.
    """
    if hasattr(llm_class, "config_class") and llm_class.config_class is not config_class:
      raise ValueError(f"The model class you are passing has a `config_class` attribute that is not consistent with the config class you passed (model has {llm_class.config_class} and you passed {config_class}. Fix one of those so they match!")
    cls._model_mapping.register(config_class, llm_class)
  @classmethod
  def infer_class_from_name(cls, name: str) -> type[openllm.LLM[t.Any, t.Any]]:
    config_class = openllm.AutoConfig.infer_class_from_name(name)
    if config_class in cls._model_mapping: return cls._model_mapping[config_class]
    raise ValueError(f"Unrecognized configuration class ({config_class}) for {name}. Model name should be one of {', '.join(openllm.CONFIG_MAPPING.keys())} (Registered configuration class: {', '.join([i.__name__ for i in cls._model_mapping.keys()])}).")

def getattribute_from_module(module: types.ModuleType, attr: t.Any) -> t.Any:
  if attr is None: return
  if isinstance(attr, tuple): return tuple(getattribute_from_module(module, a) for a in attr)
  if hasattr(module, attr): return getattr(module, attr)
  # Some of the mappings have entries model_type -> object of another model type. In that case we try to grab the object at the top level.
  openllm_module = importlib.import_module("openllm")
  if module != openllm_module:
    try: return getattribute_from_module(openllm_module, attr)
    except ValueError: raise ValueError(f"Could not find {attr} neither in {module} nor in {openllm_module}!") from None
  raise ValueError(f"Could not find {attr} in {openllm_module}!")

class _LazyAutoMapping(OrderedDict, ReprMixin):
  """Based on transformers.models.auto.configuration_auto._LazyAutoMapping.

  This OrderedDict values() and keys() returns the list instead, so you don't
  have to do list(mapping.values()) to get the list of values.
  """
  def __init__(self, config_mapping: OrderedDict[LiteralString, LiteralString], model_mapping: OrderedDict[LiteralString, LiteralString]):
    self._config_mapping = config_mapping
    self._reverse_config_mapping = {v: k for k, v in config_mapping.items()}
    self._model_mapping = model_mapping
    self._extra_content: dict[t.Any, t.Any] = {}
    self._modules: dict[str, types.ModuleType] = {}
  def __getitem__(self, key: type[openllm.LLMConfig]) -> type[openllm.LLM[t.Any, t.Any]]:
    if key in self._extra_content: return self._extra_content[key]
    model_type = self._reverse_config_mapping[key.__name__]
    if model_type in self._model_mapping: return self._load_attr_from_module(model_type, self._model_mapping[model_type])
    # Maybe there was several model types associated with this config.
    model_types = [k for k, v in self._config_mapping.items() if v == key.__name__]
    for mtype in model_types:
      if mtype in self._model_mapping: return self._load_attr_from_module(mtype, self._model_mapping[mtype])
    raise KeyError(key)
  def _load_attr_from_module(self, model_type: str, attr: str) -> t.Any:
    module_name = inflection.underscore(model_type)
    if module_name not in self._modules: self._modules[module_name] = importlib.import_module(f".{module_name}", "openllm.models")
    return getattribute_from_module(self._modules[module_name], attr)
  def __len__(self) -> int: return len(set(self._config_mapping.keys()).intersection(self._model_mapping.keys())) + len(self._extra_content)
  @property
  def __repr_keys__(self) -> set[str]: return set(self._config_mapping.keys())
  def __repr__(self) -> str: return ReprMixin.__repr__(self)
  def __repr_args__(self) -> t.Generator[tuple[str, tuple[str, str]], t.Any, t.Any]: yield from ((key, (value, self._model_mapping[key])) for key, value in self._config_mapping.items() if key in self._model_mapping)
  def __bool__(self) -> bool: return bool(self.keys())
  def keys(self) -> ConfigModelKeysView: return t.cast("ConfigModelKeysView", [self._load_attr_from_module(key, name) for key, name in self._config_mapping.items() if key in self._model_mapping.keys()] + list(self._extra_content.keys()))
  def values(self) -> ConfigModelValuesView: return t.cast("ConfigModelValuesView", [self._load_attr_from_module(key, name) for key, name in self._model_mapping.items() if key in self._config_mapping.keys()] + list(self._extra_content.values()))
  def items(self) -> ConfigModelItemsView: return t.cast("ConfigModelItemsView", [(self._load_attr_from_module(key, self._config_mapping[key]), self._load_attr_from_module(key, self._model_mapping[key])) for key in self._model_mapping.keys() if key in self._config_mapping.keys()] + list(self._extra_content.items()))
  def __iter__(self) -> t.Iterator[type[openllm.LLMConfig]]: return iter(t.cast("SupportsIter[t.Iterator[type[openllm.LLMConfig]]]", self.keys()))
  def __contains__(self, item: t.Any) -> bool:
    if item in self._extra_content: return True
    if not hasattr(item, "__name__") or item.__name__ not in self._reverse_config_mapping: return False
    return self._reverse_config_mapping[item.__name__] in self._model_mapping
  def register(self, key: t.Any, value: t.Any) -> None:
    if hasattr(key, "__name__") and key.__name__ in self._reverse_config_mapping:
      if self._reverse_config_mapping[key.__name__] in self._model_mapping.keys(): raise ValueError(f"'{key}' is already used by a OpenLLM model.")
    self._extra_content[key] = value
__all__ = ["BaseAutoLLMClass", "_LazyAutoMapping"]

# mypy: disable-error-code="misc"
"""OCI-related utilities for OpenLLM. This module is considered to be internal and API are subjected to change."""
from __future__ import annotations
import functools, importlib, logging, os, pathlib, shutil, subprocess, typing as t
from datetime import datetime, timedelta, timezone
import attr, orjson, bentoml, openllm
from openllm.utils.lazy import VersionInfo

if t.TYPE_CHECKING:
  from ghapi import all
  from openllm._typing_compat import RefTuple, LiteralString

all = openllm.utils.LazyLoader("all", globals(), "ghapi.all")  # noqa: F811

logger = logging.getLogger(__name__)

_BUILDER = bentoml.container.get_backend("buildx")
ROOT_DIR = pathlib.Path(os.path.abspath("__file__")).parent.parent.parent

# TODO: support quay
LiteralContainerRegistry = t.Literal["docker", "gh", "ecr"]
LiteralContainerVersionStrategy = t.Literal["release", "nightly", "latest", "custom"]

# XXX: This registry will be hard code for now for easier to maintain
# but in the future, we can infer based on git repo and everything to make it more options for users
# to build the base image. For now, all of the base image will be <registry>/bentoml/openllm:...
# NOTE: The ECR registry is the public one and currently only @bentoml team has access to push it.
_CONTAINER_REGISTRY: dict[LiteralContainerRegistry, str] = {"docker": "docker.io/bentoml/openllm", "gh": "ghcr.io/bentoml/openllm", "ecr": "public.ecr.aws/y5w8i4y6/bentoml/openllm"}

# TODO: support custom fork. Currently it only support openllm main.
_OWNER = "bentoml"
_REPO = "openllm"

_module_location = openllm.utils.pkg.source_locations("openllm")

@functools.lru_cache
@openllm.utils.apply(str.lower)
def get_base_container_name(reg: LiteralContainerRegistry) -> str: return _CONTAINER_REGISTRY[reg]

def _convert_version_from_string(s: str) -> VersionInfo: return VersionInfo.from_version_string(s)
def _commit_time_range(r: int = 5) -> str: return (datetime.now(timezone.utc) - timedelta(days=r)).strftime("%Y-%m-%dT%H:%M:%SZ")

class VersionNotSupported(openllm.exceptions.OpenLLMException):
  """Raised when the stable release is too low that it doesn't include OpenLLM base container."""

_RefTuple: type[RefTuple] = openllm.utils.codegen.make_attr_tuple_class("_RefTuple", ["git_hash", "version", "strategy"])

def nightly_resolver(cls: type[RefResolver]) -> str:
  # NOTE: all openllm container will have sha-<git_hash[:7]>
  # This will use docker to run skopeo to determine the correct latest tag that is available
  # If docker is not found, then fallback to previous behaviour. Which the container might not exists.
  docker_bin = shutil.which("docker")
  if docker_bin is None:
    logger.warning("To get the correct available nightly container, make sure to have docker available. Fallback to previous behaviour for determine nightly hash (container might not exists due to the lack of GPU machine at a time. See https://github.com/bentoml/OpenLLM/pkgs/container/openllm for available image.)")
    commits = t.cast("list[dict[str, t.Any]]", cls._ghapi.repos.list_commits(since=_commit_time_range()))
    return next(f'sha-{it["sha"][:7]}' for it in commits if "[skip ci]" not in it["commit"]["message"])
  # now is the correct behaviour
  return orjson.loads(subprocess.check_output([docker_bin, "run", "--rm", "-it", "quay.io/skopeo/stable:latest", "list-tags", "docker://ghcr.io/bentoml/openllm"]).decode().strip())["Tags"][-2]

@attr.attrs(eq=False, order=False, slots=True, frozen=True)
class RefResolver:
  git_hash: str = attr.field()
  version: openllm.utils.VersionInfo = attr.field(converter=_convert_version_from_string)
  strategy: LiteralContainerVersionStrategy = attr.field()
  _ghapi: t.ClassVar[all.GhApi] = all.GhApi(owner=_OWNER, repo=_REPO)
  @classmethod
  def _nightly_ref(cls) -> RefTuple: return _RefTuple((nightly_resolver(cls), "refs/heads/main", "nightly"))
  @classmethod
  def _release_ref(cls, version_str: str | None = None) -> RefTuple:
    _use_base_strategy = version_str is None
    if version_str is None:
      # NOTE: This strategy will only support openllm>0.2.12
      meta: dict[str, t.Any] = cls._ghapi.repos.get_latest_release()
      version_str = meta["name"].lstrip("v")
      version: tuple[str, str | None] = (cls._ghapi.git.get_ref(ref=f"tags/{meta['name']}")["object"]["sha"], version_str)
    else: version = ("", version_str)
    if openllm.utils.VersionInfo.from_version_string(t.cast(str, version_str)) < (0, 2, 12): raise VersionNotSupported(f"Version {version_str} doesn't support OpenLLM base container. Consider using 'nightly' or upgrade 'openllm>=0.2.12'")
    return _RefTuple((*version, "release" if _use_base_strategy else "custom"))
  @classmethod
  @functools.lru_cache(maxsize=64)
  def from_strategy(cls, strategy_or_version: t.Literal["release", "nightly"] | LiteralString | None = None) -> RefResolver:
    # using default strategy
    if strategy_or_version is None or strategy_or_version == "release": return cls(*cls._release_ref())
    elif strategy_or_version == "latest": return cls("latest", "0.0.0", "latest")
    elif strategy_or_version == "nightly":
      _ref = cls._nightly_ref()
      return cls(_ref[0], "0.0.0", _ref[-1])
    else:
      logger.warning("Using custom %s. Make sure that it is at lease 0.2.12 for base container support.", strategy_or_version)
      return cls(*cls._release_ref(version_str=strategy_or_version))
  @property
  def tag(self) -> str:
    # NOTE: latest tag can also be nightly, but discouraged to use it. For nightly refer to use sha-<git_hash_short>
    if self.strategy == "latest": return "latest"
    elif self.strategy == "nightly": return self.git_hash
    else: return repr(self.version)

@functools.lru_cache(maxsize=256)
def get_base_container_tag(strategy: LiteralContainerVersionStrategy | None = None) -> str: return RefResolver.from_strategy(strategy).tag
def build_container(registries: LiteralContainerRegistry | t.Sequence[LiteralContainerRegistry] | None = None, version_strategy: LiteralContainerVersionStrategy = "release", push: bool = False, machine: bool = False) -> dict[str | LiteralContainerRegistry, str]:
  try:
    if not _BUILDER.health(): raise openllm.exceptions.Error
  except (openllm.exceptions.Error, subprocess.CalledProcessError): raise RuntimeError("Building base container requires BuildKit (via Buildx) to be installed. See https://docs.docker.com/build/buildx/install/ for instalation instruction.") from None
  if openllm.utils.device_count() == 0: raise RuntimeError("Building base container requires GPUs (None available)")
  if not shutil.which("nvidia-container-runtime"): raise RuntimeError("NVIDIA Container Toolkit is required to compile CUDA kernel in container.")
  if not _module_location: raise RuntimeError("Failed to determine source location of 'openllm'. (Possible broken installation)")
  pyproject_path = pathlib.Path(_module_location).parent.parent / "pyproject.toml"
  if not pyproject_path.exists(): raise ValueError("This utility can only be run within OpenLLM git repository. Clone it first with 'git clone https://github.com/bentoml/OpenLLM.git'")
  if not registries: tags: dict[str | LiteralContainerRegistry, str] = {alias: f"{value}:{get_base_container_tag(version_strategy)}" for alias, value in _CONTAINER_REGISTRY.items()}  # default to all registries with latest tag strategy
  else:
    registries = [registries] if isinstance(registries, str) else list(registries)
    tags = {name: f"{_CONTAINER_REGISTRY[name]}:{get_base_container_tag(version_strategy)}" for name in registries}
  try:
    outputs = _BUILDER.build(file=pathlib.Path(__file__).parent.joinpath("Dockerfile").resolve().__fspath__(), context_path=pyproject_path.parent.__fspath__(), tag=tuple(tags.values()), push=push, progress="plain" if openllm.utils.get_debug_mode() else "auto", quiet=machine)
    if machine and outputs is not None: tags["image_sha"] = outputs.decode("utf-8").strip()
  except Exception as err: raise openllm.exceptions.OpenLLMException(f"Failed to containerize base container images (Scroll up to see error above, or set OPENLLMDEVDEBUG=True for more traceback):\n{err}") from err
  return tags

if t.TYPE_CHECKING:
  CONTAINER_NAMES: dict[LiteralContainerRegistry, str]
  supported_registries: list[str]

__all__ = ["CONTAINER_NAMES", "get_base_container_tag", "build_container", "get_base_container_name", "supported_registries", "RefResolver"]
def __dir__() -> list[str]: return sorted(__all__)
def __getattr__(name: str) -> t.Any:
  if name == "supported_registries": return functools.lru_cache(1)(lambda: list(_CONTAINER_REGISTRY))()
  elif name == "CONTAINER_NAMES": return _CONTAINER_REGISTRY
  elif name in __all__: return importlib.import_module("." + name, __name__)
  else: raise AttributeError(f"{name} does not exists under {__name__}")

import configparser
import logging
import os
from dataclasses import dataclass, fields
from getpass import getpass
from pathlib import Path
from typing import Optional

from opentelemetry.exporter.otlp.proto.http.trace_exporter import OTLPSpanExporter
from opentelemetry.sdk.trace import TracerProvider
from opentelemetry.sdk.trace.export import BatchSpanProcessor, SimpleSpanProcessor

from openllmtelemetry.content_id import ContentIdProvider
from openllmtelemetry.guardrails import GuardrailsApi
from openllmtelemetry.span_exporter import DebugOTLSpanExporter

CFG_API_KEY = "api_key"

CFG_ENDPOINT_KEY = "endpoint"

CFG_LOG_PROFILE_KEY = "log_profile"

CFG_WHYLABS_SECTION = "whylabs"

CFG_GUARDRAILS_SECTION = "guardrails"

LOGGER = logging.getLogger(__name__)
_DEFAULT_ENDPOINT = "https://api.whylabsapp.com"
_CONFIG_DIR = os.path.join(Path.home(), ".whylabs")
_DEFAULT_CONFIG_FILE = os.path.join(_CONFIG_DIR, "guardrails-config.ini")

_in_ipython_session = False
try:
    # noinspection PyStatementEffect
    __IPYTHON__  # pyright: ignore[reportUndefinedVariable,reportUnusedExpression]
    _in_ipython_session = True
except NameError:
    pass


@dataclass
class GuardrailConfig(object):
    whylabs_endpoint: Optional[str] = None
    whylabs_api_key: Optional[str] = None
    guardrails_endpoint: Optional[str] = None
    guardrails_api_key: Optional[str] = None
    log_profile: Optional[str] = None

    @property
    def is_partial(self):
        return (
            self.whylabs_endpoint is None
            or self.whylabs_api_key is None
            or self.guardrails_endpoint is None
            or self.guardrails_api_key is None
        )

    @property
    def whylabs_traces_endpoint(self) -> str:
        assert self.whylabs_endpoint is not None, "WhyLabs endpoint is not set."
        return f"{self.whylabs_endpoint.rstrip('/')}/v1/traces"

    def guardrail_client(self, default_dataset_id: Optional[str], content_id_provider: Optional[ContentIdProvider] = None) -> Optional[GuardrailsApi]:
        if self.guardrails_endpoint and self.guardrails_api_key:
            return GuardrailsApi(
                guardrails_endpoint=self.guardrails_endpoint,
                guardrails_api_key=self.guardrails_api_key,
                dataset_id=default_dataset_id,
                log_profile=True if self.log_profile is None or self.log_profile.lower() == "true" else False,
                content_id_provider=content_id_provider,
            )
        LOGGER.warning("GuardRails endpoint is not set.")
        return None

    def config_tracer_provider(
        self,
        tracer_provider: TracerProvider,
        dataset_id: str,
        disable_batching: bool = False,
        debug: bool = False,
    ):
        if self.whylabs_traces_endpoint and self.whylabs_api_key:
            debug_enabled = os.environ.get("WHYLABS_DEBUG_TRACE") or debug
            whylabs_api_key_header = {"X-API-Key": self.whylabs_api_key, "X-WHYLABS-RESOURCE": dataset_id}
            # TODO: support other kinds of exporters
            if debug_enabled:
                otlp_exporter = DebugOTLSpanExporter(
                    endpoint=self.whylabs_traces_endpoint,
                    headers=whylabs_api_key_header,  # noqa: F821
                )
            else:
                otlp_exporter = OTLPSpanExporter(
                    endpoint=self.whylabs_traces_endpoint,
                    headers=whylabs_api_key_header,  # noqa: F821
                )
            if disable_batching:
                span_processor = SimpleSpanProcessor(otlp_exporter)
            else:
                span_processor = BatchSpanProcessor(otlp_exporter)
            tracer_provider.add_span_processor(span_processor)

        pass

    def write(self, config_path: str):
        config = configparser.ConfigParser()
        if self.whylabs_endpoint is not None and self.whylabs_api_key is not None:
            config[CFG_WHYLABS_SECTION] = {
                CFG_ENDPOINT_KEY: self.whylabs_endpoint,
                CFG_API_KEY: self.whylabs_api_key,
            }
        if self.guardrails_endpoint:
            config[CFG_GUARDRAILS_SECTION] = {
                CFG_ENDPOINT_KEY: self.guardrails_endpoint,
                CFG_API_KEY: self.guardrails_api_key or "",
                CFG_LOG_PROFILE_KEY: self.log_profile or "",
            }
        with open(config_path, "w") as configfile:
            config.write(configfile)

    def __repr__(self):
        # hide the api_key from output
        field_strs = [
            f"{field.name}='***key***'" if "key" in field.name else f"{field.name}={getattr(self, field.name)}" for field in fields(self)
        ]
        return f"{self.__class__.__name__}({', '.join(field_strs)})"

    @classmethod
    def read(cls, config_path: str) -> "GuardrailConfig":
        config = configparser.ConfigParser()
        ok_files = config.read(config_path)
        if len(ok_files) == 0:
            raise IOError("Failed to read the configuration file.")

        whylabs_endpoint = config.get(CFG_WHYLABS_SECTION, CFG_ENDPOINT_KEY)
        whylabs_api_key = config.get(CFG_WHYLABS_SECTION, CFG_API_KEY)
        guardrails_endpoint = config.get(CFG_GUARDRAILS_SECTION, CFG_ENDPOINT_KEY, fallback=None)
        guardrails_api_key = config.get(CFG_GUARDRAILS_SECTION, CFG_API_KEY, fallback=None)
        log_profile = config.get(CFG_GUARDRAILS_SECTION, CFG_LOG_PROFILE_KEY, fallback=None)

        return GuardrailConfig(whylabs_endpoint, whylabs_api_key, guardrails_endpoint, guardrails_api_key, log_profile)


def load_config() -> GuardrailConfig:
    config_path = os.environ.get("WHYLABS_GUARDRAILS_CONFIG")
    if config_path is None:
        config_path = _DEFAULT_CONFIG_FILE
    config = GuardrailConfig(None, None, None, None)
    try:
        config = GuardrailConfig.read(config_path)
    except:  # noqa
        LOGGER.warning("Failed to parse the configuration file")
    if config.is_partial:
        config = _load_config_from_env(config)
    if config.is_partial and _in_ipython_session:
        config = _interactive_config(config)

    return config


def load_dataset_id(dataset_id: Optional[str]) -> Optional[str]:
    effective_dataset_id = os.environ.get("WHYLABS_DEFAULT_DATASET_ID", dataset_id)
    if effective_dataset_id is None:
        if _in_ipython_session:
            effective_dataset_id = input("Set the default dataset ID: ").strip()
            if len(effective_dataset_id) > 0:
                print("Using dataset ID: ", effective_dataset_id)
            else:
                print("Dataset ID is not set. Skip tracing...")
                effective_dataset_id = None
    return effective_dataset_id


def _load_config_from_env(config: Optional[GuardrailConfig] = None) -> GuardrailConfig:
    if config is None:
        config = GuardrailConfig()
    whylabs_endpoint = os.environ.get("WHYLABS_ENDPOINT", config.whylabs_endpoint) or _DEFAULT_ENDPOINT
    whylabs_api_key = os.environ.get("WHYLABS_API_KEY", config.whylabs_api_key)
    guardrails_endpoint = os.environ.get("GUARDRAILS_ENDPOINT", config.guardrails_endpoint)
    guardrails_api_key = os.environ.get("GUARDRAILS_API_KEY", config.guardrails_api_key)
    log_profile = os.environ.get("GUARDRAILS_LOG_PROFILE", config.log_profile)
    guardrail_config = GuardrailConfig(whylabs_endpoint, whylabs_api_key, guardrails_endpoint, guardrails_api_key, log_profile)
    return guardrail_config


def _interactive_config(config: GuardrailConfig) -> GuardrailConfig:
    whylabs_endpoint = config.whylabs_endpoint or _DEFAULT_ENDPOINT
    whylabs_api_key = config.whylabs_api_key
    guardrails_endpoint = config.guardrails_endpoint
    guardrails_api_key = config.guardrails_api_key
    if whylabs_api_key is None:
        whylabs_api_key = getpass("Set WhyLabs API Key: ").strip()
        print("Using WhyLabs API key with ID: ", whylabs_api_key[:10])
    if guardrails_endpoint is None:
        guardrails_endpoint = input("Set GuardRails endpoint (leave blank to skip guardrail): ").strip()
        if len(guardrails_endpoint) == 0:
            guardrails_endpoint = None
        if guardrails_endpoint is None:
            print("GuardRails endpoint is not set. Only tracing is enabled.")
    if guardrails_endpoint is not None and guardrails_api_key is None:
        guardrails_api_key = getpass("Set GuardRails API Key: ").strip()
        if len(guardrails_api_key) > 15:
            print("Using GuardRails API key with prefix: ", guardrails_api_key[:6])

    guardrail_config = GuardrailConfig(
        whylabs_endpoint=whylabs_endpoint,
        whylabs_api_key=whylabs_api_key,
        guardrails_endpoint=guardrails_endpoint,
        guardrails_api_key=guardrails_api_key,
    )

    save_config = input("Do you want to save these settings to a configuration file? [y/n]: ").strip().lower()
    if save_config == "y" or save_config == "yes":
        try:
            os.makedirs(_CONFIG_DIR, exist_ok=True)
            guardrail_config.write(_DEFAULT_CONFIG_FILE)
        except Exception as e:  # noqa
            LOGGER.exception(f"Failed to write the configuration file: {e}")

            print("Failed to write the configuration file.")

    print(f"Set config: {guardrail_config}")
    return guardrail_config

from __future__ import annotations
import logging, re, typing as t, openllm
from openllm._prompt import process_prompt
from openllm._typing_compat import overload
from .configuration_dolly_v2 import DEFAULT_PROMPT_TEMPLATE, END_KEY, RESPONSE_KEY, get_special_token_id

if t.TYPE_CHECKING: import torch, transformers, tensorflow as tf
else: torch, transformers, tf = openllm.utils.LazyLoader("torch", globals(), "torch"), openllm.utils.LazyLoader("transformers", globals(), "transformers"), openllm.utils.LazyLoader("tf", globals(), "tensorflow")
logger = logging.getLogger(__name__)

@overload
def get_pipeline(model: transformers.PreTrainedModel, tokenizer: transformers.PreTrainedTokenizer, _init: t.Literal[True] = True, **attrs: t.Any) -> transformers.Pipeline: ...
@overload
def get_pipeline(model: transformers.PreTrainedModel, tokenizer: transformers.PreTrainedTokenizer, _init: t.Literal[False] = ..., **attrs: t.Any) -> type[transformers.Pipeline]: ...
def get_pipeline(model: transformers.PreTrainedModel, tokenizer: transformers.PreTrainedTokenizer, _init: bool = False, **attrs: t.Any) -> type[transformers.Pipeline] | transformers.Pipeline:
  # Lazy loading the pipeline. See databricks' implementation on HuggingFace for more information.
  class InstructionTextGenerationPipeline(transformers.Pipeline):
    def __init__(self, *args: t.Any, do_sample: bool = True, max_new_tokens: int = 256, top_p: float = 0.92, top_k: int = 0, **kwargs: t.Any): super().__init__(*args, model=model, tokenizer=tokenizer, do_sample=do_sample, max_new_tokens=max_new_tokens, top_p=top_p, top_k=top_k, **kwargs)
    def _sanitize_parameters(self, return_full_text: bool | None = None, **generate_kwargs: t.Any) -> tuple[dict[str, t.Any], dict[str, t.Any], dict[str, t.Any]]:
      if t.TYPE_CHECKING: assert self.tokenizer is not None
      preprocess_params: dict[str, t.Any] = {}
      # newer versions of the tokenizer configure the response key as a special token.  newer versions still may
      # append a newline to yield a single token.  find whatever token is configured for the response key.
      tokenizer_response_key = next((token for token in self.tokenizer.additional_special_tokens if token.startswith(RESPONSE_KEY)), None)
      response_key_token_id = None
      end_key_token_id = None
      if tokenizer_response_key:
        try:
          response_key_token_id = get_special_token_id(self.tokenizer, tokenizer_response_key)
          end_key_token_id = get_special_token_id(self.tokenizer, END_KEY)
          # Ensure generation stops once it generates "### End"
          generate_kwargs["eos_token_id"] = end_key_token_id
        except ValueError: pass
      forward_params = generate_kwargs
      postprocess_params = {"response_key_token_id": response_key_token_id, "end_key_token_id": end_key_token_id}
      if return_full_text is not None: postprocess_params["return_full_text"] = return_full_text
      return preprocess_params, forward_params, postprocess_params
    def preprocess(self, input_: str, **generate_kwargs: t.Any) -> t.Dict[str, t.Any]:
      if t.TYPE_CHECKING: assert self.tokenizer is not None
      prompt_text = DEFAULT_PROMPT_TEMPLATE.format(instruction=input_)
      inputs = self.tokenizer(prompt_text, return_tensors="pt")
      inputs["prompt_text"] = prompt_text
      inputs["instruction_text"] = input_
      return t.cast(t.Dict[str, t.Any], inputs)
    def _forward(self, input_tensors: dict[str, t.Any], **generate_kwargs: t.Any) -> transformers.utils.generic.ModelOutput:
      if t.TYPE_CHECKING: assert self.tokenizer is not None
      input_ids, attention_mask = input_tensors["input_ids"], input_tensors.get("attention_mask", None)
      if input_ids.shape[1] == 0: input_ids, attention_mask, in_b = None, None, 1
      else: in_b = input_ids.shape[0]
      generated_sequence = self.model.generate(input_ids=input_ids.to(self.model.device) if input_ids is not None else None, attention_mask=attention_mask.to(self.model.device) if attention_mask is not None else None, pad_token_id=self.tokenizer.pad_token_id, **generate_kwargs)
      out_b = generated_sequence.shape[0]
      if self.framework == "pt": generated_sequence = generated_sequence.reshape(in_b, out_b // in_b, *generated_sequence.shape[1:])
      elif self.framework == "tf": generated_sequence = tf.reshape(generated_sequence, (in_b, out_b // in_b, *generated_sequence.shape[1:]))
      instruction_text = input_tensors.pop("instruction_text")
      return {"generated_sequence": generated_sequence, "input_ids": input_ids, "instruction_text": instruction_text}
    def postprocess(self, model_outputs: dict[str, t.Any], response_key_token_id: int, end_key_token_id: int, return_full_text: bool = False) -> list[dict[t.Literal["generated_text"], str]]:
      if t.TYPE_CHECKING: assert self.tokenizer is not None
      _generated_sequence, instruction_text = model_outputs["generated_sequence"][0], model_outputs["instruction_text"]
      generated_sequence: list[list[int]] = _generated_sequence.numpy().tolist()
      records: list[dict[t.Literal["generated_text"], str]] = []
      for sequence in generated_sequence:
        # The response will be set to this variable if we can identify it.
        decoded = None
        # If we have token IDs for the response and end, then we can find the tokens and only decode between them.
        if response_key_token_id and end_key_token_id:
          # Find where "### Response:" is first found in the generated tokens.  Considering this is part of the
          # prompt, we should definitely find it.  We will return the tokens found after this token.
          try: response_pos = sequence.index(response_key_token_id)
          except ValueError: response_pos = None
          if response_pos is None: logger.warning("Could not find response key %s in: %s", response_key_token_id, sequence)
          if response_pos:
            # Next find where "### End" is located.  The model has been trained to end its responses with this
            # sequence (or actually, the token ID it maps to, since it is a special token).  We may not find
            # this token, as the response could be truncated.  If we don't find it then just return everything
            # to the end.  Note that even though we set eos_token_id, we still see the this token at the end.
            try: end_pos = sequence.index(end_key_token_id)
            except ValueError: end_pos = None
            decoded = self.tokenizer.decode(sequence[response_pos + 1:end_pos]).strip()
        if not decoded:
          # Otherwise we'll decode everything and use a regex to find the response and end.
          fully_decoded = self.tokenizer.decode(sequence)
          # The response appears after "### Response:".  The model has been trained to append "### End" at the
          # end.
          m = re.search(r"#+\s*Response:\s*(.+?)#+\s*End", fully_decoded, flags=re.DOTALL)
          if m: decoded = m.group(1).strip()
          else:
            # The model might not generate the "### End" sequence before reaching the max tokens.  In this case,
            # return everything after "### Response:".
            m = re.search(r"#+\s*Response:\s*(.+)", fully_decoded, flags=re.DOTALL)
            if m: decoded = m.group(1).strip()
            else: logger.warning("Failed to find response in:\n%s", fully_decoded)
        # If the full text is requested, then append the decoded text to the original instruction.
        # This technically isn't the full text, as we format the instruction in the prompt the model has been
        # trained on, but to the client it will appear to be the full text.
        if return_full_text: decoded = f"{instruction_text}\n{decoded}"
        records.append({"generated_text": t.cast(str, decoded)})
      return records
  return InstructionTextGenerationPipeline() if _init else InstructionTextGenerationPipeline

class DollyV2(openllm.LLM["transformers.Pipeline", "transformers.PreTrainedTokenizer"]):
  __openllm_internal__ = True
  @property
  def import_kwargs(self) -> tuple[dict[str, t.Any], dict[str, t.Any]]: return {"device_map": "auto" if torch.cuda.is_available() and torch.cuda.device_count() > 1 else None, "torch_dtype": torch.bfloat16}, {}
  def load_model(self, *args: t.Any, **attrs: t.Any) -> transformers.Pipeline: return get_pipeline(transformers.AutoModelForCausalLM.from_pretrained(self._bentomodel.path, *args, **attrs), self.tokenizer, _init=True, return_full_text=self.config.return_full_text)
  def sanitize_parameters(self, prompt: str, max_new_tokens: int | None = None, temperature: float | None = None, top_k: int | None = None, top_p: float | None = None, use_default_prompt_template: bool = True, **attrs: t.Any) -> tuple[str, dict[str, t.Any], dict[str, t.Any]]: return process_prompt(prompt, DEFAULT_PROMPT_TEMPLATE, use_default_prompt_template, **attrs), {"max_new_tokens": max_new_tokens, "top_k": top_k, "top_p": top_p, "temperature": temperature, **attrs}, {}
  def postprocess_generate(self, prompt: str, generation_result: list[dict[t.Literal["generated_text"], str]], **_: t.Any) -> str: return generation_result[0]["generated_text"]
  def generate(self, prompt: str, **attrs: t.Any) -> list[dict[t.Literal["generated_text"], str]]:
    llm_config = self.config.model_construct_env(**attrs)
    with torch.inference_mode(): return self.model(prompt, return_full_text=llm_config.return_full_text, generation_config=llm_config.to_generation_config())

