from __future__ import annotations

import asyncio
import typing as t
from abc import abstractmethod
from urllib.parse import urljoin

import httpx

import bentoml
import openllm
import transformers


# NOTE: We need to do this so that overload can register
# correct overloads to typing registry
if hasattr(t, "get_overloads"):
    from typing import overload
else:
    from typing_extensions import overload

if t.TYPE_CHECKING:
    from openllm.models.auto.factory import _BaseAutoLLMClass

    class AnnotatedClient(bentoml.client.Client):
        def health(self, *args: t.Any, **attrs: t.Any) -> t.Any:
            ...

        async def async_health(self) -> t.Any:
            ...

        def call(self, name: str, inputs: t.Any, **attrs: t.Any) -> t.Any:
            ...

        async def acall(self, name: str, inputs: t.Any, **attrs: t.Any) -> t.Any:
            ...

        def generate_v1(self, qa: openllm.GenerationInput) -> dict[str, t.Any]:
            ...

        def metadata_v1(self) -> dict[str, t.Any]:
            ...


def in_async_context() -> bool:
    try:
        _ = asyncio.get_running_loop()
        return True
    except RuntimeError:
        return False


class ClientMixin:
    _api_version: str
    _client_class: type[bentoml.client.Client]

    _host: str
    _port: str

    __client__: AnnotatedClient | None = None
    __agent__: transformers.HfAgent | None = None
    __llm__: openllm.LLM[t.Any, t.Any] | None = None

    def __init__(self, address: str, timeout: int = 30):
        self._address = address
        self._timeout = timeout
        assert self._host and self._port, "Make sure to setup _host and _port based on your client implementation."

    def __init_subclass__(cls, *, client_type: t.Literal["http", "grpc"] = "http", api_version: str = "v1"):
        cls._client_class = bentoml.client.HTTPClient if client_type == "http" else bentoml.client.GrpcClient
        cls._api_version = api_version

    @property
    def _hf_agent(self) -> transformers.HfAgent:
        if self.__agent__ is None:
            if not openllm.utils.is_transformers_supports_agent():
                raise RuntimeError(
                    "Current 'transformers' does not support Agent."
                    " Make sure to upgrade to at least 4.29: 'pip install -U \"transformers>=4.29\"'"
                )
            self.__agent__ = transformers.HfAgent(urljoin(self._address, "/hf/agent"))
        return self.__agent__

    @property
    def _metadata(self) -> dict[str, t.Any]:
        if in_async_context():
            return httpx.post(urljoin(self._address, f"/{self._api_version}/metadata")).json()
        return self.call("metadata")

    @property
    @abstractmethod
    def model_name(self) -> str:
        raise NotImplementedError

    @property
    @abstractmethod
    def framework(self) -> t.Literal["pt", "flax", "tf"]:
        raise NotImplementedError

    @property
    @abstractmethod
    def timeout(self) -> int:
        raise NotImplementedError

    @property
    @abstractmethod
    def model_id(self) -> str:
        raise NotImplementedError

    @property
    @abstractmethod
    def configuration(self) -> dict[str, t.Any]:
        raise NotImplementedError

    @property
    def llm(self) -> openllm.LLM[t.Any, t.Any]:
        if self.__llm__ is None:
            self.__llm__ = t.cast(
                "_BaseAutoLLMClass",
                openllm[self.framework],  # type: ignore (internal API)
            ).for_model(self.model_name)
        return self.__llm__

    @property
    def config(self) -> openllm.LLMConfig:
        return self.llm.config

    def call(self, name: str, *args: t.Any, **attrs: t.Any) -> t.Any:
        return self._cached.call(f"{name}_{self._api_version}", *args, **attrs)

    async def acall(self, name: str, *args: t.Any, **attrs: t.Any) -> t.Any:
        return await self._cached.async_call(f"{name}_{self._api_version}", *args, **attrs)

    @property
    def _cached(self) -> AnnotatedClient:
        if self.__client__ is None:
            self._client_class.wait_until_server_ready(self._host, int(self._port), timeout=self._timeout)
            self.__client__ = t.cast("AnnotatedClient", self._client_class.from_url(self._address))
        return self.__client__

    def prepare(self, prompt: str, **attrs: t.Any):
        return_raw_response = attrs.pop("return_raw_response", False)
        return return_raw_response, *self.llm.sanitize_parameters(prompt, **attrs)

    @abstractmethod
    def postprocess(self, result: t.Any) -> openllm.GenerationOutput:
        ...

    @abstractmethod
    def _run_hf_agent(self, *args: t.Any, **kwargs: t.Any) -> t.Any:
        ...


class BaseClient(ClientMixin):
    def health(self) -> t.Any:
        raise NotImplementedError

    @overload
    def query(self, prompt: str, *, return_raw_response: t.Literal[False] = ..., **attrs: t.Any) -> str:
        ...

    @overload
    def query(self, prompt: str, *, return_raw_response: t.Literal[True] = ..., **attrs: t.Any) -> dict[str, t.Any]:
        ...

    def query(self, prompt: str, **attrs: t.Any) -> dict[str, t.Any] | str:
        return_raw_response, prompt, generate_kwargs, postprocess_kwargs = self.prepare(prompt, **attrs)
        inputs = openllm.GenerationInput(prompt=prompt, llm_config=self.config.model_construct_env(**generate_kwargs))
        if in_async_context():
            result = httpx.post(
                urljoin(self._address, f"/{self._api_version}/generate"),
                json=openllm.utils.bentoml_cattr.unstructure(inputs),
                timeout=self.timeout,
            ).json()
        else:
            result = self.call("generate", inputs)
        r = self.postprocess(result)

        if return_raw_response:
            return openllm.utils.bentoml_cattr.unstructure(r)

        return self.llm.postprocess_generate(prompt, r.responses, **postprocess_kwargs)

    def ask_agent(
        self,
        task: str,
        *,
        return_code: bool = False,
        remote: bool = False,
        agent_type: t.LiteralString = "hf",
        **attrs: t.Any,
    ) -> t.Any:
        if agent_type == "hf":
            return self._run_hf_agent(task, return_code=return_code, remote=remote, **attrs)
        else:
            raise RuntimeError(f"Unknown 'agent_type={agent_type}'")

    def _run_hf_agent(self, *args: t.Any, **kwargs: t.Any) -> t.Any:
        if len(args) > 1:
            raise ValueError("'args' should only take one positional argument.")
        task = kwargs.pop("task", args[0])
        return_code = kwargs.pop("return_code", False)
        remote = kwargs.pop("remote", False)
        return self._hf_agent.run(task, return_code=return_code, remote=remote, **kwargs)

    # NOTE: Scikit interface
    def predict(self, prompt: str, **attrs: t.Any) -> t.Any:
        return self.query(prompt, **attrs)

    def chat(self, prompt: str, history: list[str], **attrs: t.Any) -> str:
        raise NotImplementedError


class BaseAsyncClient(ClientMixin):
    async def health(self) -> t.Any:
        raise NotImplementedError

    @overload
    async def query(self, prompt: str, *, return_raw_response: t.Literal[False] = ..., **attrs: t.Any) -> str:
        ...

    @overload
    async def query(
        self, prompt: str, *, return_raw_response: t.Literal[True] = ..., **attrs: t.Any
    ) -> dict[str, t.Any]:
        ...

    async def query(self, prompt: str, **attrs: t.Any) -> dict[str, t.Any] | str:
        # NOTE: We set use_default_prompt_template to False for now.
        use_default_prompt_template = attrs.pop("use_default_prompt_template", False)
        return_raw_response, prompt, generate_kwargs, postprocess_kwargs = self.prepare(
            prompt, use_default_prompt_template=use_default_prompt_template, **attrs
        )
        inputs = openllm.GenerationInput(prompt=prompt, llm_config=self.config.model_construct_env(**generate_kwargs))
        res = await self.acall("generate", inputs)
        r = self.postprocess(res)

        if return_raw_response:
            return openllm.utils.bentoml_cattr.unstructure(r)

        return self.llm.postprocess_generate(prompt, r.responses, **postprocess_kwargs)

    async def ask_agent(
        self,
        task: str,
        *,
        return_code: bool = False,
        remote: bool = False,
        agent_type: t.LiteralString = "hf",
        **attrs: t.Any,
    ) -> t.Any:
        """Async version of agent.run"""
        if agent_type == "hf":
            return await self._run_hf_agent(task, return_code=return_code, remote=remote, **attrs)
        else:
            raise RuntimeError(f"Unknown 'agent_type={agent_type}'")

    async def _run_hf_agent(self, *args: t.Any, **kwargs: t.Any) -> t.Any:
        if len(args) > 1:
            raise ValueError("'args' should only take one positional argument.")
        task = kwargs.pop("task", args[0])
        return_code = kwargs.pop("return_code", False)
        remote = kwargs.pop("remote", False)

        from transformers.tools.agents import clean_code_for_run
        from transformers.tools.agents import get_tool_creation_code
        from transformers.tools.agents import resolve_tools
        from transformers.tools.python_interpreter import evaluate

        _hf_agent = self._hf_agent

        prompt = _hf_agent.format_prompt(task)
        stop = ["Task:"]
        async with httpx.AsyncClient(timeout=httpx.Timeout(self.timeout)) as client:
            response = await client.post(
                _hf_agent.url_endpoint,
                json={
                    "inputs": prompt,
                    "parameters": {"max_new_tokens": 200, "return_full_text": False, "stop": stop},
                },
            )
            if response.status_code != 200:
                raise ValueError(f"Error {response.status_code}: {response.json()}")

        result = response.json()[0]["generated_text"]
        # Inference API returns the stop sequence
        for stop_seq in stop:
            if result.endswith(stop_seq):
                result = result[: -len(stop_seq)]
                break

        # the below have the same logic as agent.run API
        explanation, code = clean_code_for_run(result)

        _hf_agent.log(f"==Explanation from the agent==\n{explanation}")

        _hf_agent.log(f"\n\n==Code generated by the agent==\n{code}")
        if not return_code:
            _hf_agent.log("\n\n==Result==")
            _hf_agent.cached_tools = resolve_tools(
                code, _hf_agent.toolbox, remote=remote, cached_tools=_hf_agent.cached_tools
            )
            return evaluate(code, _hf_agent.cached_tools, state=kwargs.copy())
        else:
            tool_code = get_tool_creation_code(code, _hf_agent.toolbox, remote=remote)
            return f"{tool_code}\n{code}"

    # NOTE: Scikit interface
    async def predict(self, prompt: str, **attrs: t.Any) -> t.Any:
        return await self.query(prompt, **attrs)

    def chat(self, prompt: str, history: list[str], **attrs: t.Any) -> str:
        raise NotImplementedError

from __future__ import annotations

import asyncio, asyncio.subprocess, functools, hashlib, io, json, os, pathlib, signal, subprocess, sys, sysconfig, typing, shlex
import typer, typer.core, pydantic, questionary, pyaml, yaml

from collections import UserDict
from contextlib import asynccontextmanager, contextmanager
from typing_extensions import override

from pydantic_core import core_schema


ERROR_STYLE = 'red'
SUCCESS_STYLE = 'green'

OPENLLM_HOME = pathlib.Path(os.getenv('OPENLLM_HOME', pathlib.Path.home() / '.openllm'))

REPO_DIR = OPENLLM_HOME / 'repos'
TEMP_DIR = OPENLLM_HOME / 'temp'
VENV_DIR = OPENLLM_HOME / 'venv'

REPO_DIR.mkdir(exist_ok=True, parents=True)
TEMP_DIR.mkdir(exist_ok=True, parents=True)
VENV_DIR.mkdir(exist_ok=True, parents=True)

CONFIG_FILE = OPENLLM_HOME / 'config.json'

CHECKED = 'Yes'

T = typing.TypeVar('T')


class ContextVar(typing.Generic[T]):
  def __init__(self, default: T):
    self._stack: list[T] = []
    self._default = default

  def get(self) -> T:
    if self._stack:
      return self._stack[-1]
    return self._default

  def set(self, value: T) -> None:
    self._stack.append(value)

  @contextmanager
  def patch(self, value: T) -> typing.Iterator[None]:
    self._stack.append(value)
    try:
      yield
    finally:
      self._stack.pop()


VERBOSE_LEVEL = ContextVar(0)
INTERACTIVE = ContextVar(False)


def output(
  content: typing.Any, level: int = 0, style: str | None = None, end: str | None = None
) -> None:
  if level > VERBOSE_LEVEL.get():
    return

  if not isinstance(content, str):
    out = io.StringIO()
    pyaml.pprint(content, dst=out, sort_dicts=False, sort_keys=False)
    questionary.print(out.getvalue(), style=style, end='' if end is None else end)
    out.close()
  else:
    questionary.print(content, style=style, end='\n' if end is None else end)


class Config(pydantic.BaseModel):
  repos: dict[str, str] = pydantic.Field(
    default_factory=lambda: {
      'default': 'https://github.com/bentoml/openllm-models@main',
      'nightly': 'https://github.com/bentoml/openllm-models@nightly',
    }
  )
  default_repo: str = 'default'

  def tolist(self) -> dict[str, typing.Any]:
    return dict(repos=self.repos, default_repo=self.default_repo)


def load_config() -> Config:
  if CONFIG_FILE.exists():
    try:
      with open(CONFIG_FILE) as f:
        return Config(**json.load(f))
    except json.JSONDecodeError:
      return Config()
  return Config()


def save_config(config: Config) -> None:
  with open(CONFIG_FILE, 'w') as f:
    json.dump(config.tolist(), f, indent=2)


class BentoMetadata(typing.TypedDict):
  name: str
  version: str
  labels: dict[str, str]
  envs: list[dict[str, str]]
  services: list[dict[str, typing.Any]]
  schema: dict[str, typing.Any]


class EnvVars(UserDict[str, str]):
  """
  A dictionary-like object that sorted by key and only keeps the environment variables that have a value.
  """

  @classmethod
  def __get_pydantic_core_schema__(
    cls: type[EnvVars], source_type: type[typing.Any], handler: typing.Callable[..., typing.Any]
  ) -> core_schema.DictSchema:
    return core_schema.dict_schema(core_schema.str_schema(), core_schema.str_schema())

  def __init__(self, data: typing.Mapping[str, str] | None = None):
    super().__init__(data or {})
    self.data = {k: v for k, v in sorted(self.data.items()) if v}

  def __hash__(self) -> int:
    return hash(tuple(sorted(self.data.items())))


class RepoInfo(pydantic.BaseModel):
  name: str
  path: pathlib.Path
  url: str
  server: str
  owner: str
  repo: str
  branch: str

  def tolist(self) -> str | dict[str, typing.Any] | None:
    if VERBOSE_LEVEL.get() <= 0:
      return f'{self.name} ({self.url}@{self.branch})'
    if VERBOSE_LEVEL.get() <= 10:
      return dict(name=self.name, url=f'{self.url}@{self.branch}', path=str(self.path))
    if VERBOSE_LEVEL.get() <= 20:
      return dict(
        name=self.name,
        url=f'{self.url}@{self.branch}',
        path=str(self.path),
        server=self.server,
        owner=self.owner,
        repo=self.repo,
      )
    return None


class BentoInfo(pydantic.BaseModel):
  repo: RepoInfo
  path: pathlib.Path
  alias: str = ''

  def __str__(self) -> str:
    if self.repo.name == 'default':
      return f'{self.tag}'
    else:
      return f'{self.repo.name}/{self.tag}'

  @override
  def __hash__(self) -> int:
    return md5(str(self.path))

  @property
  def tag(self) -> str:
    if self.alias:
      return f'{self.path.parent.name}:{self.alias}'
    return f'{self.path.parent.name}:{self.path.name}'

  @property
  def bentoml_tag(self) -> str:
    return f'{self.path.parent.name}:{self.path.name}'

  @property
  def name(self) -> str:
    return self.path.parent.name

  @property
  def version(self) -> str:
    return self.path.name

  @property
  def labels(self) -> dict[str, str]:
    return self.bento_yaml['labels']

  @property
  def envs(self) -> list[dict[str, str]]:
    return self.bento_yaml['envs']

  @functools.cached_property
  def bento_yaml(self) -> BentoMetadata:
    bento: BentoMetadata = yaml.safe_load((self.path / 'bento.yaml').read_text())
    return bento

  @functools.cached_property
  def platforms(self) -> list[str]:
    return self.bento_yaml['labels'].get('platforms', 'linux').split(',')

  @functools.cached_property
  def pretty_yaml(self) -> BentoMetadata | dict[str, typing.Any]:
    def _pretty_routes(routes: list[dict[str, typing.Any]]) -> dict[str, typing.Any]:
      return {
        route['route']: {
          'input': {k: v['type'] for k, v in route['input']['properties'].items()},
          'output': route['output']['type'],
        }
        for route in routes
      }

    if len(self.bento_yaml['services']) == 1:
      pretty_yaml: dict[str, typing.Any] = {
        'apis': _pretty_routes(self.bento_yaml['schema']['routes']),
        'resources': self.bento_yaml['services'][0]['config']['resources'],
        'envs': self.bento_yaml['envs'],
        'platforms': self.platforms,
      }
      return pretty_yaml
    return self.bento_yaml

  @functools.cached_property
  def pretty_gpu(self) -> str:
    from openllm.accelerator_spec import ACCELERATOR_SPECS

    try:
      resources = self.bento_yaml['services'][0]['config']['resources']
      if resources['gpu'] > 1:
        acc = ACCELERATOR_SPECS[resources['gpu_type']]
        return f'{acc.memory_size:.0f}Gx{resources["gpu"]}'
      elif resources['gpu'] > 0:
        acc = ACCELERATOR_SPECS[resources['gpu_type']]
        return f'{acc.memory_size:.0f}G'
    except KeyError:
      pass
    return ''

  def tolist(self) -> str | dict[str, typing.Any] | None:
    verbose = VERBOSE_LEVEL.get()
    if verbose <= 0:
      return str(self)
    if verbose <= 10:
      return dict(
        tag=self.tag, repo=self.repo.tolist(), path=str(self.path), model_card=self.pretty_yaml
      )
    if verbose <= 20:
      return dict(
        tag=self.tag, repo=self.repo.tolist(), path=str(self.path), bento_yaml=self.bento_yaml
      )
    return None


class VenvSpec(pydantic.BaseModel):
  python_version: str
  requirements_txt: str
  envs: EnvVars
  name_prefix: str = ''

  @functools.cached_property
  def normalized_requirements_txt(self) -> str:
    parameter_lines: list[str] = []
    dependency_lines: list[str] = []
    comment_lines: list[str] = []

    for line in self.requirements_txt.splitlines():
      if not line.strip():
        continue
      elif line.strip().startswith('#'):
        comment_lines.append(line.strip())
      elif line.strip().startswith('-'):
        parameter_lines.append(line.strip())
      else:
        dependency_lines.append(line.strip())

    parameter_lines.sort()
    dependency_lines.sort()
    return '\n'.join(parameter_lines + dependency_lines).strip()

  @functools.cached_property
  def normalized_envs(self) -> str:
    return '\n'.join(f'{k}={v}' for k, v in sorted(self.envs.items(), key=lambda x: x[0]) if not v)

  @override
  def __hash__(self) -> int:
    return md5(self.normalized_requirements_txt, str(hash(self.normalized_envs)))


class Accelerator(pydantic.BaseModel):
  model: str
  memory_size: float

  def __gt__(self, other: Accelerator) -> bool:
    return self.memory_size > other.memory_size

  def __eq__(self, other: object) -> bool:
    if not isinstance(other, Accelerator):
      return NotImplemented
    return self.memory_size == other.memory_size

  def __repr__(self) -> str:
    return f'{self.model}({self.memory_size}GB)'


class DeploymentTarget(pydantic.BaseModel):
  accelerators: list[Accelerator]
  source: str = 'local'
  name: str = 'local'
  price: str = ''
  platform: str = 'linux'

  @override
  def __hash__(self) -> int:
    return hash(self.source)

  @property
  def accelerators_repr(self) -> str:
    accs = {a.model for a in self.accelerators}
    if len(accs) == 0:
      return 'null'
    if len(accs) == 1:
      a = self.accelerators[0]
      return f'{a.model} x{len(self.accelerators)}'
    return ', '.join((f'{a.model}' for a in self.accelerators))


def run_command(
  cmd: list[str],
  cwd: str | None = None,
  env: EnvVars | None = None,
  copy_env: bool = True,
  venv: pathlib.Path | None = None,
  silent: bool = False,
) -> subprocess.CompletedProcess[typing.Any]:
  env = env or EnvVars({})
  cmd = [str(c) for c in cmd]
  bin_dir = 'Scripts' if os.name == 'nt' else 'bin'
  if not silent:
    output('\n')
    if cwd:
      output(f'$ cd {cwd}', style='orange')
    if env:
      for k, v in env.items():
        output(f'$ export {k}={shlex.quote(v)}', style='orange')
    if venv:
      output(f'$ source {venv / "bin" / "activate"}', style='orange')
    output(f'$ {" ".join(cmd)}', style='orange')

  if venv:
    py = venv / bin_dir / f'python{sysconfig.get_config_var("EXE")}'
  else:
    py = pathlib.Path(sys.executable)

  if copy_env:
    env = EnvVars({**os.environ, **env})

  if cmd and cmd[0] == 'bentoml':
    cmd = [py.__fspath__(), '-m', 'bentoml', *cmd[1:]]
  if cmd and cmd[0] == 'python':
    cmd = [py.__fspath__(), *cmd[1:]]

  try:
    if silent:
      return subprocess.run(
        cmd, cwd=cwd, env=env, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=True
      )
    else:
      return subprocess.run(cmd, cwd=cwd, env=env, check=True)
  except Exception as e:
    if VERBOSE_LEVEL.get() >= 20:
      output(str(e), style='red')
    raise typer.Exit(1)


async def stream_command_output(
  stream: asyncio.streams.StreamReader | None, style: str = 'gray'
) -> None:
  if stream:
    async for line in stream:
      output(line.decode(), style=style, end='')


@asynccontextmanager
async def async_run_command(
  cmd: list[str],
  cwd: str | None = None,
  env: EnvVars | None = None,
  copy_env: bool = True,
  venv: pathlib.Path | None = None,
  silent: bool = True,
) -> typing.AsyncGenerator[asyncio.subprocess.Process]:
  env = env or EnvVars({})
  cmd = [str(c) for c in cmd]

  if not silent:
    output('\n')
    if cwd:
      output(f'$ cd {cwd}', style='orange')
    if env:
      for k, v in env.items():
        output(f'$ export {k}={shlex.quote(v)}', style='orange')
    if venv:
      output(f'$ source {venv / "bin" / "activate"}', style='orange')
    output(f'$ {" ".join(cmd)}', style='orange')

  if venv:
    py = venv / 'bin' / 'python'
  else:
    py = pathlib.Path(sys.executable)

  if copy_env:
    env = EnvVars({**os.environ, **env})

  if cmd and cmd[0] == 'bentoml':
    cmd = [py.__fspath__(), '-m', 'bentoml', *cmd[1:]]
  if cmd and cmd[0] == 'python':
    cmd = [py.__fspath__(), *cmd[1:]]

  proc = None
  try:
    proc = await asyncio.create_subprocess_shell(
      ' '.join(map(str, cmd)),
      stdout=asyncio.subprocess.PIPE,
      stderr=asyncio.subprocess.PIPE,
      cwd=cwd,
      env=env,
    )
    yield proc
  except subprocess.CalledProcessError:
    output('Command failed', style='red')
    raise typer.Exit(1)
  finally:
    if proc:
      proc.send_signal(signal.SIGINT)
      await proc.wait()


def md5(*strings: str) -> int:
  m = hashlib.md5()
  for s in strings:
    m.update(s.encode())
  return int(m.hexdigest(), 16)

