from common import start_benchmark_session, get_tokenizer, get_prompt_set
import asyncio

class UserDef:
    # BASE_URL = "http://llama27bchat-org-ss-org-1--aws-us-east-1.mt2.bentoml.ai"
    # BASE_URL= "http://llama2-7b-org-ss-org-1--aws-us-east-1.mt2.bentoml.ai"
    # BASE_URL = "http://llama2-13b-org-ss-org-1--aws-us-east-1.mt2.bentoml.ai"
    # BASE_URL = "http://184.105.5.107:3000"
    BASE_URL = "http://184.105.217.197:3000"  # Aaron's machine

    @classmethod
    def ping_url(cls):
        return f"{cls.BASE_URL}/healthz"

    @classmethod
    def make_request(cls):
        """
        return url, headers, body
        """
        import openllm
        import json
        import random

        prompt = random.choice(get_prompt_set(15, 25))

        headers = {"accept": "application/json", "Content-Type": "application/json"}
        config = (
            openllm.AutoConfig.for_model("llama")
            .model_construct_env(max_new_tokens=20, top_p=0.21)
            .model_dump()
        )
        data = {"prompt": prompt, "llm_config": config, "adapter_name": None}
        url = f"{cls.BASE_URL}/v1/generate_stream"
        return url, headers, json.dumps(data)

    @classmethod
    def parse_response(cls, chunk):
        """
        take chunk and return list of tokens, used for token counting
        """
        text = chunk.decode("utf-8").strip()
        return get_tokenizer()(text)

    @staticmethod
    async def rest():
        import asyncio

        await asyncio.sleep(0.01)


if __name__ == "__main__":
    asyncio.run(start_benchmark_session(UserDef))

from flask import Flask, request, jsonify
from langchain.llms import OpenLLM
from langflow import load_flow_from_json
import requests

app = Flask(__name__)

# Initialize OpenLLM
llm_openllm = OpenLLM(model_name="llama", model_id='meta-llama/Llama-2-7b-hf')

# Load LangFlow chain
langflow_chain = load_flow_from_json("path_to_langflow.json")

@app.route('/')
def home():
    return jsonify({"message": "Welcome to our API!"}), 200

@app.route('/openllm', methods=['POST'])
def openllm():
    try:
        data = request.get_json()
        result = llm_openllm(data["query"])
        return jsonify({"result": result}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 400

@app.route('/langflow', methods=['POST'])
def langflow():
    try:
        data = request.get_json()
        result = langflow_chain(data["text"])
        return jsonify({"result": result}), 200 
    except Exception as e:
        return jsonify({"error": str(e)}), 400

@app.route('/flowise', methods=['POST'])
def flowise():
    try:
        data = request.get_json()
        response = requests.post('http://0.0.0.0:3010/flowise_endpoint', json=data)

        # Check if request to the Flowise service was successful
        if response.status_code == 200:
            result = response.json()
            return jsonify(result), 200
        else:
            return jsonify({"error": "Flowise service unavailable"}), 400
    except Exception as e:
        return jsonify({"error": str(e)}), 400

if __name__ == '__main__':
    app.run(debug=True)

from __future__ import annotations

import click
import inflection
import orjson

import bentoml
import openllm
from bentoml._internal.utils import human_readable_size

from .. import termui
from .._factory import LiteralOutput, output_option

@click.command("list_bentos", context_settings=termui.CONTEXT_SETTINGS)
@output_option(default_value="json")
@click.pass_context
def cli(ctx: click.Context, output: LiteralOutput) -> None:
  """List available bentos built by OpenLLM."""
  mapping = {
      k: [{"tag": str(b.tag), "size": human_readable_size(openllm.utils.calc_dir_size(b.path)), "models": [{"tag": str(m.tag), "size": human_readable_size(openllm.utils.calc_dir_size(m.path))} for m in (bentoml.models.get(_.tag) for _ in b.info.models)]}
          for b in tuple(i for i in bentoml.list() if all(k in i.info.labels for k in {"start_name", "bundler"})) if b.info.labels["start_name"] == k] for k in tuple(inflection.dasherize(key) for key in openllm.CONFIG_MAPPING.keys())
  }
  mapping = {k: v for k, v in mapping.items() if v}
  if output == "pretty":
    import tabulate
    tabulate.PRESERVE_WHITESPACE = True
    termui.echo(tabulate.tabulate([(k, i["tag"], i["size"], [_["tag"] for _ in i["models"]]) for k, v in mapping.items() for i in v], tablefmt="fancy_grid", headers=["LLM", "Tag", "Size", "Models"]), fg="white")
  else:
    termui.echo(orjson.dumps(mapping, option=orjson.OPT_INDENT_2).decode(), fg="white")
  ctx.exit(0)

import os

import pytest

from core.model_runtime.entities.text_embedding_entities import TextEmbeddingResult
from core.model_runtime.errors.validate import CredentialsValidateFailedError
from core.model_runtime.model_providers.openllm.text_embedding.text_embedding import OpenLLMTextEmbeddingModel


def test_validate_credentials():
    model = OpenLLMTextEmbeddingModel()

    with pytest.raises(CredentialsValidateFailedError):
        model.validate_credentials(
            model='NOT IMPORTANT',
            credentials={
                'server_url': 'ww' + os.environ.get('OPENLLM_SERVER_URL'),
            }
        )

    model.validate_credentials(
        model='NOT IMPORTANT',
        credentials={
            'server_url': os.environ.get('OPENLLM_SERVER_URL'),
        }
    )


def test_invoke_model():
    model = OpenLLMTextEmbeddingModel()

    result = model.invoke(
        model='NOT IMPORTANT',
        credentials={
            'server_url': os.environ.get('OPENLLM_SERVER_URL'),
        },
        texts=[
            "hello",
            "world"
        ],
        user="abc-123"
    )

    assert isinstance(result, TextEmbeddingResult)
    assert len(result.embeddings) == 2
    assert result.usage.total_tokens > 0

def test_get_num_tokens():
    model = OpenLLMTextEmbeddingModel()

    num_tokens = model.get_num_tokens(
        model='NOT IMPORTANT',
        credentials={
            'server_url': os.environ.get('OPENLLM_SERVER_URL'),
        },
        texts=[
            "hello",
            "world"
        ]
    )

    assert num_tokens == 2

