from transformers import AutoTokenizer, AutoModelForCausalLM, pipeline
from llm.model_names import mistral_model
from utils.utils import select_gpu_if_available
from langchain_community.llms import OpenLLM


class LlmModel:
    is_open_llm: bool
    _instance = None

    def __new__(cls, *args, **kwargs):
        if not cls._instance:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self, model_name=mistral_model, is_open_llm=False):

        self.is_open_llm = is_open_llm

        if is_open_llm:
            self.model = OpenLLM(server_url="http://localhost:3000")

        else:
            dtype = select_gpu_if_available()
            self.tokenizer = AutoTokenizer.from_pretrained(
                model_name, trust_remote_code=True, use_fast=False
            )
            self.model = AutoModelForCausalLM.from_pretrained(
                model_name,
                torch_dtype=dtype,
                device_map="auto",
            )

            self.pipeline = pipeline(
                task="text-generation",
                model=self.model,
                tokenizer=self.tokenizer,
                device_map="auto",
                max_new_tokens=1000,
                return_full_text=False,
            )

    def generate_text(self, input_text: str):
        if self.is_open_llm:
            return self.model.invoke(input_text)
        else:
            inputs = self.tokenizer.encode(
                text=input_text,
                return_tensors="pt",
            )

            output = self.model.generate(inputs)

            generated_text = self.tokenizer.batch_decode(
                output, skip_special_tokens=True, device_map="auto"
            )
            return " ".join(generated_text)

    def cleanup(self):

        if not self.is_open_llm:
            del self.tokenizer

        # Delete references to the model
        del self.model

        # Empty gpu cache
        from torch.cuda import empty_cache

        empty_cache()

        # Perform garbage collection to release memory
        from gc import collect

        collect()

from typing import List, Optional, Any

from langchain.callbacks.manager import Callbacks
from langchain.schema import LLMResult

from core.model_providers.error import LLMBadRequestError
from core.model_providers.models.llm.base import BaseLLM
from core.model_providers.models.entity.message import PromptMessage
from core.model_providers.models.entity.model_params import ModelMode, ModelKwargs
from core.third_party.langchain.llms.openllm import OpenLLM


class OpenLLMModel(BaseLLM):
    model_mode: ModelMode = ModelMode.COMPLETION

    def _init_client(self) -> Any:
        self.provider_model_kwargs = self._to_model_kwargs_input(self.model_rules, self.model_kwargs)

        client = OpenLLM(
            server_url=self.credentials.get('server_url'),
            callbacks=self.callbacks,
            llm_kwargs=self.provider_model_kwargs
        )

        return client

    def _run(self, messages: List[PromptMessage],
             stop: Optional[List[str]] = None,
             callbacks: Callbacks = None,
             **kwargs) -> LLMResult:
        """
        run predict by prompt messages and stop words.

        :param messages:
        :param stop:
        :param callbacks:
        :return:
        """
        prompts = self._get_prompt_from_messages(messages)
        return self._client.generate([prompts], stop, callbacks)

    def get_num_tokens(self, messages: List[PromptMessage]) -> int:
        """
        get num tokens of prompt messages.

        :param messages:
        :return:
        """
        prompts = self._get_prompt_from_messages(messages)
        return max(self._client.get_num_tokens(prompts), 0)

    def prompt_file_name(self, mode: str) -> str:
        if 'baichuan' in self.name.lower():
            if mode == 'completion':
                return 'baichuan_completion'
            else:
                return 'baichuan_chat'
        else:
            return super().prompt_file_name(mode)

    def _set_model_kwargs(self, model_kwargs: ModelKwargs):
        pass

    def handle_exceptions(self, ex: Exception) -> Exception:
        return LLMBadRequestError(f"OpenLLM: {str(ex)}")

